function saveAssetEdit(i){const el=document.getElementById('genericAssetEdit'),change=el?el.value.trim():'';if(!change)return;archiveDownstream(i,assetDef(i).name+' edited',{label:'Owner edit',before:'Previous accepted or generated version'});const key=stages[i].id;if(!state.customMessages[key])state.customMessages[key]=[];state.customMessages[key].push(assistantMessage(`<p class="answer-intro">A new draft version was created after the campaign owner edited this asset.</p><div class="callout info"><div><strong>Owner change</strong><br>${esc(change)}</div></div>`));closeModal();renderAll();toast('New draft version created');}

