 comments.push({initials:'SC',name:'Sarah Chen',role:'Campaign Owner · Editor',time:'Just now',location:location?location.value:'Overall asset',text,selected:true,incorporated:false,replies:[]});addActivity('New owner comment added to '+activeCommentData().asset);renderAll();state.commentsOpen=true;renderRight();toast('Comment added and selected');
