function regenerateBriefFromChat(){
 const input=document.getElementById('composerInput'),instruction=input?input.value.trim():'';if(!instruction){if(input){input.focus();input.placeholder='Add regeneration instructions here, then click Regenerate brief…';}toast('Add your regeneration instructions in the chat box first');return;}
 input.value='';runAssetRegeneration(1,'Regenerating campaign brief from chat instructions',()=>{archiveDownstream(1,'Campaign brief regenerated from a new chat instruction');state.briefVersion+=1;state.lastBriefInstruction=instruction;const key=stages[1].id;if(!state.customMessages[key])state.customMessages[key]=[];state.customMessages[key].push(userMessage(instruction));state.customMessages[key].push(assistantMessage(`<p class="answer-intro">I regenerated the campaign brief as <strong>version ${state.briefVersion}.0</strong> using your additional instruction.</p><div class="callout success">${ICON.check}<div><strong>Instruction applied</strong><br>${esc(instruction)}</div></div>`));});
}
function editBrief(){state.commentAsset={type:'brief',index:null};state.commentsOpen=false;state.rightMode='context';renderRight();toast('Edit any field; changing it will create a new workflow version');setTimeout(()=>{const el=document.querySelector('.brief-field textarea');if(el)el.focus();},50);}
function acceptBrief(){if(state.acceptedAssets[1]){toast('Campaign brief is already accepted');return;}beginAssetRegistration(1,'Campaign brief');}
function toggleSource(key){state.connections[key]=!state.connections[key];renderConnectorState();toast(`${key.charAt(0).toUpperCase()+key.slice(1)} ${state.connections[key]?'connected':'disconnected'}`);}
function renderConnectorState(){['teams','outlook','sharepoint'].forEach(k=>{const el=document.getElementById('source-'+k);if(el)el.classList.toggle('connected',!!state.connections[k]);});}
function generateBriefFromSources(promptText){
 const connected=Object.values(state.connections).filter(Boolean).length;if(!connected){toast('Select at least one connected source');return;}
 state.initialPrompt=promptText||document.getElementById('composerInput').value.trim()||stages[0].prompt;state.campaignName=/i-?portal/i.test(state.initialPrompt)?'iPortal Digital Engagement Campaign':'New Campaign';state.started=true;state.sourceSearchComplete=true;state.completed.add(0);state.stage=1;state.focusStage=1;addActivity('Connected sources searched and relevant iPortal documents selected');beginStageGeneration(1,'Generating complete campaign brief',state.initialPrompt);
}
function handleSuggestion(text){
 if(state.started&&state.acceptedAssets[state.stage]&&assetDef(state.stage).nextStageIndex!==null){const input=document.getElementById('composerInput');input.value=text;input.focus();return;}
 if(text.startsWith('Next:')){const input=document.getElementById('composerInput');input.value=text.replace(/^Next:\s*/,'');input.focus();return;}
 quickSend(text);
}
function userMessage(text){return `<div class="message user"><div class="bubble">${esc(text)}</div><div class="avatar">SC</div></div>`;}
function assistantMessage(content){return `<div class="message assistant"><div class="avatar">${ICON.bot}</div><div class="bubble"><div class="assistant-label">Campaign Coordinator</div>${content}</div></div>`;}
function stageHeader(i,title,desc){return `<div class="stage-banner"><div><div class="eyebrow">Stage ${i+1} of ${stages.length}</div><h2>${esc(title)}</h2><p>${esc(desc)}</p></div><span class="status-chip ${state.completed.has(i)?'complete':''}">${state.completed.has(i)?'Completed':'In progress'}</span></div>`;}
function channelTags(){return `<div class="tag-row">${state.channels.map(c=>`<span class="tag blue">${esc(c)}</span>`).join('')}</div>`;}
function startEmptyState(){return `<div class="start-empty"><div class="start-orb">${ICON.bot}</div><h1>Create an iPortal campaign brief</h1><p>Select the collaboration sources below, then ask the Campaign Coordinator to find the relevant iPortal material and generate the complete brief.</p></div>`;}
function renderConversation(){
 let html='';
 for(let i=(state.hideInputTranscript?1:0);i<=state.stage;i++){
  const st=stages[i];let content='';
  if(i===0){content=userMessage(state.initialPrompt)+assistantMessage(renderInput());}
  else if(state.generatingStage===i&&state.inlineOperationStage!==i){content=(i>1?userMessage(state.stagePrompts[i]||st.prompt):'')+assistantMessage(renderGeneratingState(i));}
  else if(i===1){content=assistantMessage(renderBrief()+renderAcceptedAsset(i));}
  else if(i===2&&!state.segmentGenerated){content=userMessage(state.stagePrompts[i]||st.prompt)+assistantMessage(renderGeneratingState(i));}
  else{content=userMessage(state.stagePrompts[i]||st.prompt)+assistantMessage(renderStage(i)+renderAcceptedAsset(i));}
  content+=(state.customMessages[st.id]||[]).join('');html+=`<section class="conversation-stage" id="conversation-stage-${i}"><div class="stage-anchor-label">${esc(st.name)}</div>${content}</section>`;
 }
 return html;
}
function renderAll(options={}){
 const root=document.getElementById('appRoot');const chat=document.getElementById('chatScroll');const previousScroll=chat?chat.scrollTop:0;
 root.classList.toggle('not-started',!state.started);renderNav();
 document.getElementById('topCampaign').textContent=state.generatedAssets[1]?state.campaignName:'New campaign';
 const current=stages[state.stage];document.getElementById('agentSub').textContent=state.started?current.sub:'Select sources and describe the brief you need';
 if(state.started)renderRight();else document.getElementById('rightPanel').innerHTML='';
 let prompts;
 if(state.generatingStage!==null||state.savingStage!==null){prompts=[];}
 else if(!state.started){prompts=['Search Teams, Outlook and SharePoint for iPortal-related documents and generate a complete campaign brief'];}
 else if(state.acceptedAssets[state.stage]&&assetDef(state.stage).nextPrompt){prompts=[assetDef(state.stage).nextPrompt];}
 else{prompts=current.suggestions;}
 document.getElementById('suggestions').innerHTML=prompts.map(x=>`<button class="suggestion" data-prompt="${esc(x)}" onclick="handleSuggestion(this.dataset.prompt)">${esc(x)}</button>`).join('');
 const connectors=document.getElementById('sourceConnectors');connectors.classList.toggle('visible',!state.started);document.getElementById('groundingLabel').textContent=!state.started?'Choose sources · then send':state.savingStage!==null?'Saving accepted asset':'Grounded campaign response';renderConnectorState();const composer=document.querySelector('.composer'),composerInput=document.getElementById('composerInput'),busy=state.generatingStage!==null||state.savingStage!==null;composer.classList.toggle('generating',state.generatingStage!==null);composer.classList.toggle('saving',state.savingStage!==null);composerInput.disabled=busy;if(!busy&&state.acceptedAssets[state.stage]&&assetDef(state.stage).nextPrompt)composerInput.placeholder=assetDef(state.stage).nextPrompt;else if(!busy)composerInput.placeholder='Ask Campaign Coordinator to refine the current asset or create the next asset…';
 document.getElementById('chatInner').innerHTML=state.started?renderConversation():startEmptyState();
 requestAnimationFrame(()=>{
  if(options.scrollToStage!==undefined){const el=document.getElementById('conversation-stage-'+options.scrollToStage);if(el)el.scrollIntoView({behavior:'smooth',block:'start'});}
  else if(options.bottom){chat.scrollTop=chat.scrollHeight;}
  else{chat.scrollTop=previousScroll;}
 });
}
function quickSend(text){document.getElementById('composerInput').value=text;sendMessage();}
function sendMessage(){
 const input=document.getElementById('composerInput');const text=input.value.trim();if(!text)return;if(state.generatingStage!==null||state.savingStage!==null){toast('Please wait for the current operation to finish');return;}
 if(!state.started){input.value='';generateBriefFromSources(text);return;}
 if(state.acceptedAssets[state.stage]&&assetDef(state.stage).nextStageIndex!==null){const nextIndex=assetDef(state.stage).nextStageIndex;input.value='';generateNextStage(nextIndex,text);return;}
 if(state.stage===2&&!state.segmentGenerated){input.value='';generateSegments(text);return;}
 input.value='';const s=stages[state.stage];if(!state.customMessages[s.id])state.customMessages[s.id]=[];state.customMessages[s.id].push(userMessage(text));renderAll({bottom:true});
 const typing=`<div class="message assistant" id="typing"><div class="avatar">${ICON.bot}</div><div class="bubble"><div class="assistant-label">Campaign Coordinator</div><div class="generation-card" style="margin:0"><div class="generation-visual"><div class="generation-doc">${ICON.bot}</div></div><div class="generation-copy"><h3>Thinking <span class="thinking-dots"><span></span><span></span><span></span></span></h3><p>Applying the current campaign context and accepted assets.</p><div class="generation-time">Generating a grounded response · approximately 5 seconds</div></div></div></div></div>`;document.getElementById('chatInner').insertAdjacentHTML('beforeend',typing);scrollBottom();
 setTimeout(()=>{const response=assistantMessage(genericResponse(text));state.customMessages[s.id].push(response);renderAll({bottom:true});},5000);
}
function scrollBottom(){requestAnimationFrame(()=>{const c=document.getElementById('chatScroll');c.scrollTop=c.scrollHeight;});}
function genericResponse(text){const q=text.toLowerCase();
 if(q.includes('search')&&(q.includes('iportal')||q.includes('i-portal')||q.includes('connected source')))return `<p class="answer-intro">I searched the connected Teams, Outlook and SharePoint workspaces and found <strong>seven iPortal-related documents</strong>. Three have the strongest relevance and are selected as primary grounding sources.</p><div class="search-results"><div class="search-result">${ICON.file}<div><strong>iPortal Digital Engagement Campaign Brief</strong><span>Campaign intent, budget, audiences and KPI framework</span></div><span class="source-badge">SharePoint</span></div><div class="search-result">${ICON.file}<div><strong>iPortal Messaging Workshop</strong><span>Value pillars, cohort messaging and approved language</span></div><span class="source-badge">Teams</span></div><div class="search-result">${ICON.file}<div><strong>iPortal Roadmap Review</strong><span>Capabilities, roadmap context and claim support</span></div><span class="source-badge">Outlook</span></div></div><div class="msg-actions"><button class="btn primary" onclick="generateBriefFromSources()">Generate complete campaign brief</button></div>`;
 if(q.includes('generate')&&q.includes('brief'))return `<p class="answer-intro">The connected sources are ready. I will create the complete four-section, 28-field campaign brief and preserve assumptions, evidence gaps and source lineage.</p><div class="msg-actions"><button class="btn primary" onclick="generateBriefFromSources()">Generate campaign brief</button></div>`;
 if(q.includes('missing'))return `<p class="answer-intro">The most material missing item is the <strong>validated current adoption baseline</strong>. I have kept the +15% ambition as a working target, not a confirmed forecast.</p><div class="callout warning">${ICON.warn}<div><strong>Open evidence gap</strong><br>Confirm the active-user baseline, campaign-eligible population and whether LinkedIn view-through measurement is permitted before final approval.</div></div>`;
 if(q.includes('leadership')||q.includes('summar'))return `<p class="answer-intro">Leadership summary: use iPortal as the single digital front door, prioritise the 11,431 CSIDs with the strongest adoption opportunity, activate through Email and LinkedIn, and measure active users plus feature usage depth.</p><div class="msg-actions"><button class="btn primary" onclick="toast('Leadership summary copied')">Copy summary</button></div>`;
 if(q.includes('why')&&q.includes('segment'))return `<p class="answer-intro">The selected segments combine <strong>high addressable volume, a clear behavioural barrier and deterministic CSID rules</strong>. Self-Service Opportunity has the clearest route to assisted-service reduction; Digital Adoption has the clearest route to first meaningful use.</p>`;
 if(q.includes('email'))return `<p class="answer-intro">Here is a concise Digital Adoption email variant.</p><div class="asset-preview"><div class="email-preview"><strong>Discover what is possible with iPortal</strong><p>Make day-to-day banking simpler with one digital place for payments, reporting and self-service. Explore the capabilities available to your team today.</p></div></div>`;
 if(q.includes('compliance')||q.includes('claim'))return `<p class="answer-intro">Mandatory wording, claim evidence and accessibility requirements are retained inside the Campaign Brief, Production Plan, GenStudio requests and channel-output metadata rather than being handled in a separate approval stage.</p>`;
 if(q.includes('approv'))return `<p class="answer-intro">Each remaining campaign asset is accepted and registered in sequence. The launch handoff consolidates the accepted brief, segments, KPI plan, production plan, selected assets and channel outputs into one audit-ready record.</p>`;
 return `<p class="answer-intro">I have applied your request to the current stage. In this experience, the assistant responds with the recommendation, evidence, unresolved risk and the editable campaign artifact in the same conversation.</p><div class="callout info"><div><strong>Current context retained</strong><br>Your brief, audience selections, channels, approvals and production decisions remain available across the full workflow.</div></div>`;
}
