function renderInput(){const connected=Object.entries(state.connections).filter(([,v])=>v).map(([k])=>k.charAt(0).toUpperCase()+k.slice(1));return `${stageHeader(0,'Connected-source search','The Campaign Coordinator searched the selected collaboration sources before generating the brief.')}
 <p class="answer-intro">I searched <strong>${esc(connected.join(', '))}</strong> for iPortal campaign, messaging, roadmap, audience and measurement material. Seven documents matched; the three strongest sources were used to ground the campaign brief.</p>
 <div class="source-search-summary"><div class="search-result">${ICON.file}<div><strong>iPortal Digital Engagement Campaign Brief</strong><span>Campaign need, budget, audiences and KPI framework</span></div><span class="source-badge">SharePoint</span></div><div class="search-result">${ICON.file}<div><strong>iPortal Messaging Workshop</strong><span>Value pillars, cohort messaging and approved language</span></div><span class="source-badge">Teams</span></div><div class="search-result">${ICON.file}<div><strong>iPortal Roadmap Review</strong><span>Capabilities, roadmap context and claim support</span></div><span class="source-badge">Outlook</span></div></div>
 <div class="callout warning">${ICON.warn}<div><strong>Evidence gap retained</strong><br>The exact active-user adoption baseline was not found and is explicitly marked as unconfirmed in the generated brief.</div></div>`;}
function renderInlineSectionComments(sectionIndex){
 const prefix='Section '+(sectionIndex+1);const comments=state.comments.filter(c=>c.location.startsWith(prefix)||(sectionIndex===0&&c.location==='Overall brief'));
 return `<div class="inline-discussion"><div class="inline-discussion-head"><strong>Section discussion · ${comments.length} comment${comments.length===1?'':'s'}</strong><button onclick="openComments()">Open full collaboration thread →</button></div>${comments.length?comments.map((c,i)=>{const actualIndex=state.comments.indexOf(c);return `<div class="inline-thread"><div class="inline-thread-top"><div class="comment-avatar">${esc(c.initials)}</div><div class="inline-thread-author"><strong>${esc(c.name)}</strong><span>${esc(c.role)} · ${esc(c.time)}</span></div><label class="comment-select-wrap"><input class="comment-select" type="checkbox" ${c.selected?'checked':''} ${c.incorporated?'disabled':''} onchange="toggleComment(${actualIndex})"><span>${c.incorporated?'Used':'Use'}</span></label></div><p>${esc(c.text)}</p>${(c.replies||[]).length?`<div class="inline-replies">${c.replies.map(r=>`<div class="inline-reply"><strong>${esc(r.name)}:</strong> ${esc(r.text)}</div>`).join('')}</div>`:''}</div>`;}).join(''):`<div class="inline-empty">No comments yet for this section.</div>`}</div>`;
}
function renderBrief(){const openComments=state.commentsOpen;const selectedComments=state.comments.filter(c=>c.selected&&!c.incorporated).length;return `${stageHeader(1,'Complete campaign brief','The complete editable brief is shown as one continuous four-section asset, with collaboration available from the asset header.')}

 <p class="answer-intro">I generated the <strong>complete 28-field campaign brief</strong>. The output preserves the original four-section structure and separates evidence from assumptions. Reviewer discussion is available from the collaborator control in the asset header.</p>
 <div class="answer-section"><h3><span class="num">1</span> Synthesis</h3><p>The strategy shifts the proposition from migration and access toward practical digital outcomes: simpler servicing, better visibility and more confident self-service. Email drives deterministic activation; LinkedIn supports awareness and retargeting.</p></div>
 <div class="callout info"><div><strong>Grounding method</strong><br>SharePoint supplied the operating model, budget, audience and KPIs; Teams supplied the messaging workshop and value pillars; Outlook supplied roadmap and capability context.</div></div>
 <div class="generated-wrap"><div class="asset-created-marker"><div class="asset-icon">${ICON.file}</div><span>Asset<br>generated</span></div><div class="artifact"><div class="artifact-head"><div class="artifact-title">${ICON.file}${esc(state.campaignName)} · Complete campaign brief</div><div class="artifact-head-right">${state.briefId?`<span class="brief-id">${esc(state.briefId)}</span>`:''}<span class="status-chip">${state.briefId?'Accepted':'Draft'} v${state.briefVersion}.0</span><button class="collaborator-trigger ${openComments?'active':''}" onclick="openComments()" title="Open collaborator comments"><span class="avatar-stack"><span>JM</span><span>AR</span><span>PK</span><span>+2</span></span><span class="comment-count">${state.comments.length}</span></button></div></div><div class="artifact-body">
  <div class="brief-all-sections">${briefSections.map((sec,sectionIndex)=>`<div class="brief-panel full-section"><div class="brief-section-head"><h4>Section ${sectionIndex+1} · ${esc(sec.name)}</h4><span class="status-chip complete">${sec.fields.length} fields</span></div><div class="brief-fields">${sec.fields.map(([key,label,val],idx)=>`<div class="brief-field ${(val.length>190||idx===sec.fields.length-1)?'full':''}"><label>${esc(label)}</label><textarea rows="${Math.min(7,Math.max(3,Math.ceil(val.length/90)))}" onfocus="this.dataset.before=this.value" onchange="applyBriefFieldEdit(this,${sectionIndex},${idx},'${label.replace(/'/g,"\'")}')">${esc(val)}</textarea></div>`).join('')}</div></div>`).join('')}</div>
  <div class="callout warning" style="margin-bottom:${state.lastBriefInstruction?'9px':'0'}">${ICON.warn}<div><strong>Assumption and missing information</strong><br>Quarterly growth baseline is assumed from the latest internal adoption report. Exact current adoption percentage remains unconfirmed.</div></div>${state.lastBriefInstruction?`<div class="callout success" style="margin-bottom:0">${ICON.check}<div><strong>Latest regeneration input</strong><br>${esc(state.lastBriefInstruction)}</div></div>`:''}
 </div><div class="artifact-actions"><button class="btn" ${state.generatingStage!==null||state.savingStage!==null?'disabled':''} onclick="editBrief()">Edit brief</button><button class="btn" ${selectedComments&&state.generatingStage===null&&state.savingStage===null?'':'disabled'} onclick="regenerateFromComments()">Generate with collaborator comments (${selectedComments})</button><button class="btn" ${state.generatingStage!==null||state.savingStage!==null?'disabled':''} onclick="regenerateBriefFromChat()">Regenerate using chat instructions</button><button class="btn primary" ${state.acceptedAssets[1]||state.generatingStage!==null||state.savingStage!==null?'disabled':''} onclick="acceptBrief()">${state.acceptedAssets[1]?'Accepted':'Accept full brief'}</button><div class="asset-action-hint">Select comments in the collaboration pane for feedback-led regeneration. Type a new instruction in the main composer for standard regeneration. Acceptance is saved and registered before an ID is returned.</div>${renderInlineOperation(1)}</div></div></div>`;}
function renderSegmentDiscoveryPrompt(){return `${stageHeader(2,'Discover relevant segments','The accepted brief is ready to be translated into deterministic, activatable audience segments.')}<div class="segment-discovery"><h3>Brief ${esc(state.briefId||'accepted')} is ready for audience discovery</h3><p>I can now analyse the business objective, eligibility rules, product usage and channel constraints to create the relevant target segments. Select the suggested prompt below or write your own audience-discovery instruction.</p><button class="btn primary" onclick="quickSend('Discover the relevant segments for this accepted iPortal campaign brief')">Discover relevant segments</button></div>`;}
function generateSegments(prompt){state.segmentPrompt=prompt;beginStageGeneration(2,'Generating audience segments',prompt);}
function renderSegments(){const selected=state.segments.filter(x=>x.selected),total=state.segments.reduce((a,b)=>a+b.count,0);return `${stageHeader(2,'Audience segmentation','Generated segment assets include deterministic rules, activation detail, collaboration and suppression controls.')}<p class="answer-intro">I recommend prioritising <strong>Self-Service Opportunity</strong> and <strong>Digital Adoption</strong>. Together they represent ${selected.reduce((a,b)=>a+b.count,0).toLocaleString('en-GB')} selected CSIDs and have the clearest behavioural barriers the campaign can address.</p><div class="metric-grid"><div class="metric"><span>Total segments</span><strong>${state.segments.length}</strong></div><div class="metric"><span>Total audience</span><strong>${total.toLocaleString('en-GB')}</strong></div><div class="metric"><span>Selected</span><strong>${selected.length}</strong></div></div><div class="artifact"><div class="artifact-head"><div class="artifact-title">${assetIconForStage(2)}Generated audience segment assets</div>${renderAssetHeaderRight(2,selected.length+' selected')}</div><div class="artifact-body"><div class="segment-list">${state.segments.map((s,i)=>`<div class="generated-wrap segment-generated"><div class="asset-created-marker"><div class="asset-icon">${ICON.file}</div><span>Segment<br>generated</span></div><div class="segment-asset-card ${s.selected?'selected':''}"><div class="segment-card-head"><label class="segment-select"><input type="checkbox" ${s.selected?'checked':''} onchange="toggleSegment(${i})">Select</label><div class="segment-heading"><h4>${esc(s.name)}</h4><p>${s.count.toLocaleString('en-GB')} CSIDs · ${esc(s.channel)}</p></div><div class="segment-card-tools"><button class="clone-btn" onclick="cloneSegment(${i})">Clone</button><button class="collaborator-trigger segment-collaborator" onclick="openSegmentComments(${i})" title="Open segment discussion"><span class="avatar-stack"><span>PK</span><span>JM</span><span>+1</span></span><span class="comment-count">${(s.comments||[]).length}</span></button></div></div><div class="segment-card-body"><div class="rule">${esc(s.rule)}</div><p><strong>Why:</strong> ${esc(s.why)}</p><p><strong>Need:</strong> ${esc(s.needs)}</p><div class="tag-row"><span class="tag ${s.active==='Yes'?'success':'warning'}">Activatable: ${esc(s.active)}</span><button class="clone-btn" onclick="showSegmentSuppressions(${i})">View suppressions</button></div></div></div></div>`).join('')}</div>${state.addSegmentOpen?renderAddSegmentForm():''}${state.suppressionsOpen?renderSuppressions():''}</div><div class="artifact-actions">${renderStandardAssetActions(2,'Accept '+selected.length+' segments',`acceptStageAsset(2,'Audience segment set')`,`<button class="btn" onclick="addSegment()">${ICON.plus}Add segment</button><button class="btn" onclick="toggleSuppressions()">${state.suppressionsOpen?'Hide':'View'} all suppressions</button>`)}</div></div>`;}
function toggleSegment(i){archiveDownstream(2,'Audience segment selection changed');state.segments[i].selected=!state.segments[i].selected;addActivity(`${state.segments[i].name} ${state.segments[i].selected?'selected':'excluded'}`);renderAll();}
function addSegment(){openAddSegment(null);}
function cloneSegment(i){openAddSegment(i);}
function openAddSegment(cloneIndex){const s=cloneIndex===null?null:state.segments[cloneIndex];state.addSegmentOpen=true;state.segmentDraft={name:s?s.name+' — cloned variant':'',condition:s?s.rule:'',cloneIndex};renderAll();setTimeout(()=>{const el=document.getElementById('segmentCondition');if(el)el.focus();},50);}
function cancelAddSegment(){state.addSegmentOpen=false;state.segmentDraft={name:'',condition:'',cloneIndex:null};renderAll();}
function renderAddSegmentForm(){const d=state.segmentDraft,cloned=d.cloneIndex!==null;return `<div class="add-segment-panel"><h3>${cloned?'Clone segment':'Add segment'}${cloned?`<span class="clone-source">From ${esc(state.segments[d.cloneIndex].name)}</span>`:''}</h3><p>Enter the deterministic audience condition. When cloned, the source condition is pre-populated and can be adapted before generation.</p><div class="field"><label>Segment name</label><input value="${esc(d.name)}" oninput="state.segmentDraft.name=this.value" placeholder="e.g. High-value dormant clients"></div><div class="field"><label>Audience condition</label><textarea id="segmentCondition" rows="4" oninput="state.segmentDraft.condition=this.value" placeholder="Define eligibility, behaviour and product conditions…">${esc(d.condition)}</textarea></div><div class="add-segment-actions"><button class="btn" onclick="cancelAddSegment()">Cancel</button><button class="btn primary" onclick="generateSegmentFromCondition()">Generate segment</button></div></div>`;}
function generateSegmentFromCondition(){
 const d={...state.segmentDraft},condition=(d.condition||'').trim();if(!condition){toast('Enter an audience condition first');return;}
 runAssetRegeneration(2,'Generating custom audience segment',()=>{archiveDownstream(2,'A new audience segment was generated');const base=d.cloneIndex!==null?state.segments[d.cloneIndex]:null;const name=(d.name||'Custom iPortal opportunity segment').trim();state.segments.push({name,count:base?Math.max(900,Math.round(base.count*.35)):2180,selected:true,rule:condition,why:base?'A cloned audience hypothesis adapted from '+base.name+'.':'A marketer-defined audience hypothesis generated from the supplied deterministic condition.',needs:base?base.needs:'A targeted proposition aligned to the behaviour expressed in the condition.',channel:base?base.channel:'Email',active:'Partial',suppressions:base?[...base.suppressions]:['No valid marketing consent','No contactable channel','Product or capability ineligible','Strategic account exclusion'],comments:[{initials:'PK',name:'Priya Kapoor',role:'Audience Lead · Commentator',time:'Just now',location:'Generated condition',text:'Please validate the eligible population before this custom segment is activated.',selected:false,incorporated:false,replies:[]}]});state.addSegmentOpen=false;state.segmentDraft={name:'',condition:'',cloneIndex:null};});
}
function toggleSuppressions(){state.suppressionsOpen=!state.suppressionsOpen;renderAll();}
function showSegmentSuppressions(i){state.suppressionsOpen=true;renderAll();setTimeout(()=>{const el=document.getElementById('suppression-'+i);if(el)el.scrollIntoView({behavior:'smooth',block:'center'});},50);}
function renderSuppressions(){return `<div class="suppression-panel"><h3>Suppressions applied to generated segments</h3>${state.segments.map((s,i)=>`<div class="suppression-item" id="suppression-${i}"><strong>${esc(s.name)}</strong><ul>${(s.suppressions||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`).join('')}</div>`;}
function renderProduction(){const active=state.production.filter(x=>!x.removed);return `${stageHeader(4,'Production plan','The assistant converts the accepted brief, selected audiences and approved governance record into channel-specific work packages with owners, formats, audiences, timing and dependencies.')}
 <p class="answer-intro">The accepted campaign context produces <strong>${active.length} production work packages</strong> across ${esc(state.channels.join(' and '))}. Each asset is tied to an audience, brief-led proposition, owner and timing rather than being generated as an unstructured list.</p>
 <div class="answer-section"><h3><span class="num">1</span> Production logic</h3><p>Email is the deterministic activation channel and should be produced first. LinkedIn supports awareness and retargeting, so its copy and visual system should reuse approved iPortal visual assets while adapting copy and layout to platform constraints.</p></div>
 <div class="artifact"><div class="artifact-head"><div class="artifact-title">${assetIconForStage(4)}Channel production work packages</div>${renderAssetHeaderRight(4,active.length+' active assets')}</div><div class="artifact-body">${state.production.map((p,i)=>`<div class="message-card ${p.removed?'':'selected'}" style="${p.removed?'opacity:.45':''}"><div style="display:flex;justify-content:space-between;gap:10px"><div><h4>${esc(p.channel)} · ${esc(p.asset)}</h4><p><strong>Audience:</strong> ${esc(p.audience)}</p><p><strong>Message:</strong> ${esc(p.message)}</p><p><strong>Format:</strong> ${esc(p.format)}</p><div class="tag-row"><span class="tag blue">${esc(p.owner)}</span><span class="tag">${esc(p.timing)}</span></div></div><div style="display:flex;gap:6px;align-items:flex-start"><button class="collaborator-trigger" onclick="openSubAssetComments(4,'production-'+p.id,p.channel+' · '+p.asset)"><span class="avatar-stack"><span>DT</span><span>LN</span></span><span class="comment-count">${(state.subAssetComments['production-'+p.id]||[]).length}</span></button><button class="btn danger" onclick="toggleProduction(${i})">${p.removed?'Restore':'Remove'}</button></div></div></div>`).join('')}</div>
 <div class="artifact-actions">${renderStandardAssetActions(4,'Approve production plan',`acceptStageAsset(4,'Production plan')`,`<button class="btn" onclick="toast('Production dependency map opened')">View dependencies</button><button class="btn" onclick="toast('Workfront work packages created')">Create Workfront tasks</button>`)}</div></div>`;}
function toggleProduction(i){archiveDownstream(4,'Production plan changed');state.production[i].removed=!state.production[i].removed;addActivity((state.production[i].removed?'Removed: ':'Restored: ')+state.production[i].asset);renderAll();}
function damPreview(a){if(a.previewType==='email')return `<div class="dam-thumb email"><small>EMAIL HERO</small><strong>${esc(a.headline)}</strong></div>`;if(a.previewType==='social')return `<div class="dam-thumb"><small>LINKEDIN CREATIVE</small><strong>${esc(a.headline)}</strong></div>`;if(a.previewType==='generated')return `<div class="dam-thumb"><small>GENSTUDIO · ${esc(a.dimensions)}</small><strong>${esc(a.headline)}</strong></div>`;return `<div class="dam-thumb missing"><strong>No suitable asset</strong><small>${esc(a.dimensions)}</small></div>`;}
function renderDamCriteria(){if(!state.damCriteriaOpen)return `<div class="dam-criteria"><button onclick="toggleDamCriteria()"><span>View Adobe DAM search criteria</span><span>＋</span></button></div>`;const items=[['Campaign','iPortal Digital Engagement'],['Objective','Adoption and deeper feature usage'],['Audiences','Self-Service Opportunity · Digital Adoption'],['Measurement','Active users · feature usage · self-service adoption'],['Channels','Email · LinkedIn'],['Production needs','Email journey · LinkedIn web and mobile'],['Content status','Approved and reusable assets preferred'],['Market','UK · English'],['Rights','Valid client-marketing usage'],['Metadata considered','Title, content, dimensions, recency, rights and performance']];return `<div class="dam-criteria"><button onclick="toggleDamCriteria()"><span>Adobe DAM search criteria</span><span>−</span></button><div class="dam-criteria-grid">${items.map(x=>`<div class="dam-criteria-item"><label>${esc(x[0])}</label><span>${esc(x[1])}</span></div>`).join('')}</div></div>`;}
function renderDamResult(a,i){const selected=a.included;const statusClass=a.matchStatus==='Reusable'?'success':a.matchStatus.includes('No suitable')?'warning':'warning';const created=a.generated||a.adapted;return `<div class="dam-result ${selected?'selected':''}" id="dam-result-${i}"><div class="dam-result-head">${damPreview(a)}<div class="dam-result-title"><h4>${esc(a.requirement)}</h4><p>${esc(a.name)} · ${esc(a.id)}</p><div class="tag-row"><span class="tag ${statusClass}">${esc(a.matchStatus)}</span><span class="adobe-source-label">Adobe ${a.sourceType==='Requirement'?'DAM search':a.sourceType.replace('Adobe ','')}</span><span class="tag blue">Match ${esc(a.confidence)}</span></div></div><div class="dam-result-tools"><button class="collaborator-trigger" onclick="openSubAssetComments(5,'${esc(a.commentsKey)}','${esc(a.requirement.replace(/'/g,"\\'"))}')"><span class="avatar-stack"><span>LN</span><span>AR</span></span><span class="comment-count">${(state.subAssetComments[a.commentsKey]||[]).length}</span></button></div></div><div class="dam-result-body"><div class="dam-meta-grid"><div class="dam-meta"><label>Channel / format</label><span>${esc(a.channel)} · ${esc(a.format)}</span></div><div class="dam-meta"><label>Dimensions</label><span>${esc(a.dimensions)}</span></div><div class="dam-meta"><label>Approval</label><span>${esc(a.approval)}</span></div><div class="dam-meta"><label>Rights / expiry</label><span>${esc(a.rights)} · ${esc(a.expiry)}</span></div></div><p class="dam-rationale"><strong>Why this result:</strong> ${esc(a.matchReason)}</p><div class="lineage"><strong>Lineage:</strong><span>${a.adapted?`Adobe DAM ${esc(a.sourceAssetId||a.id)} → Adobe GenStudio ${esc(a.jobId)}`:a.generated?`Adobe GenStudio · ${esc(a.jobId)}`:a.found?`Adobe DAM · ${esc(a.id)}`:'Campaign requirement · no DAM match'}</span></div>${state.damGeneratingId===a.id?`<div class="genstudio-inline"><div class="genstudio-mark">Gs</div><div><strong>${a.found?'Adapting the selected DAM asset':'Creating the missing asset'} <span class="thinking-dots"><span></span><span></span><span></span></span></strong><span>Sending the creative brief to Adobe GenStudio, applying the approved route and checking format requirements.</span></div></div>`:''}${created?`<div class="created-asset-preview"><strong>${a.adapted?'Adapted asset returned by Adobe GenStudio':'New asset returned by Adobe GenStudio'}</strong><p>${esc(a.headline)} · ${esc(a.dimensions)} · Job ${esc(a.jobId)}</p><div class="asset-preview"><div class="social-preview"><small>${a.channel} · Adobe GenStudio</small><h4>${esc(a.headline)}</h4><p>${esc(a.copy)}</p><p style="margin-top:8px"><strong>${esc(a.cta)} →</strong></p></div></div><p>Review the output and select it if it is suitable for the campaign.</p></div>`:''}<div class="dam-result-actions"><label class="asset-choice"><input type="checkbox" ${selected?'checked':''} onchange="toggleAsset(${i})">Select for campaign</label>${a.found&&!a.generated?`<button class="btn" onclick="previewDamAsset(${i})">Preview asset</button><button class="btn" onclick="openGenStudioRequest(${i},'modify')">Modify in Adobe GenStudio</button><button class="btn" onclick="toast('Adobe DAM record ${esc(a.id)} opened')">Open DAM record</button>`:`${!created?`<button class="btn primary" onclick="openGenStudioRequest(${i},'create')">Create in Adobe GenStudio</button>`:`<button class="btn" onclick="openGenStudioRequest(${i},'create')">Request another version</button>`}`}</div></div></div>`;}
function renderAssets(){const selected=state.assets.filter(x=>x.included),reusable=state.assets.filter(x=>x.matchStatus==='Reusable').length,adapt=state.assets.filter(x=>x.matchStatus==='Adaptation recommended').length,gaps=state.assets.filter(x=>x.matchStatus.includes('No suitable')).length;return `${stageHeader(5,'Adobe DAM search and asset selection','The Campaign Coordinator compares approved DAM content with the accepted brief, selected audiences, approved brief record, production requirements and channel formats.')}<p class="answer-intro">I searched <strong>Adobe DAM</strong> using the accepted campaign brief, selected audiences, approved brief record, production specifications and channel formats. I reviewed 46 assets and returned the strongest reusable, adaptable and missing-format decisions.</p><div class="adobe-search-summary"><div class="adobe-summary-metric"><span>DAM assets reviewed</span><strong>46</strong></div><div class="adobe-summary-metric"><span>Reusable matches</span><strong>${reusable}</strong></div><div class="adobe-summary-metric"><span>Adaptation candidates</span><strong>${adapt}</strong></div><div class="adobe-summary-metric"><span>Asset gaps</span><strong>${gaps}</strong></div></div>${renderDamCriteria()}<div class="artifact"><div class="artifact-head"><div class="artifact-title">${assetIconForStage(5)}Adobe DAM recommendations and GenStudio requests</div>${renderAssetHeaderRight(5,selected.length+' selected')}</div><div class="artifact-body"><div class="dam-result-list">${state.assets.map(renderDamResult).join('')}</div></div><div class="artifact-actions">${renderStandardAssetActions(5,'Accept '+selected.length+' selected assets',`acceptStageAsset(5,'Asset-selection package')`,`<button class="btn" onclick="toggleDamCriteria()">${state.damCriteriaOpen?'Hide':'View'} search evidence</button>`)}</div></div>`;}
function toggleDamCriteria(){state.damCriteriaOpen=!state.damCriteriaOpen;renderAll();}
function toggleAsset(i){archiveDownstream(5,'Asset selection changed');state.assets[i].included=!state.assets[i].included;addActivity(`${state.assets[i].requirement} ${state.assets[i].included?'selected':'excluded'}`);renderAll();}
function previewDamAsset(i){const a=state.assets[i];document.getElementById('modalRoot').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal wide"><h2>${esc(a.name)}</h2><p>Adobe DAM preview · ${esc(a.id)}</p><div class="asset-preview"><div class="social-preview"><small>${esc(a.channel)} · ${esc(a.dimensions)}</small><h4>${esc(a.headline||a.requirement)}</h4><p>${esc(a.copy||a.matchReason)}</p></div></div><div class="dam-meta-grid"><div class="dam-meta"><label>Approval</label><span>${esc(a.approval)}</span></div><div class="dam-meta"><label>Rights</label><span>${esc(a.rights)}</span></div><div class="dam-meta"><label>Expiry</label><span>${esc(a.expiry)}</span></div><div class="dam-meta"><label>Match</label><span>${esc(a.confidence)}</span></div></div><div class="modal-actions"><button class="btn" onclick="closeModal()">Close</button><button class="btn primary" onclick="closeModal();toggleAsset(${i})">${a.included?'Remove selection':'Select for campaign'}</button></div></div></div>`;}
function openGenStudioRequest(i,mode){const a=state.assets[i],isModify=mode==='modify';a.genStudioContext=Object.assign({sourceId:a.id,audience:'Digital Adoption',channel:a.channel,format:a.format,dimensions:a.dimensions,lineage:(a.adapted?('Adobe DAM '+(a.sourceAssetId||a.id)+' → Adobe GenStudio '+(a.jobId||'')):(a.found?('Adobe DAM · '+a.id):'Campaign requirement · no DAM match')),requirements:'Use approved iPortal capability language. Retain high contrast, descriptive alt text and sufficient safe area for responsive crops.'},a.genStudioContext||{});document.getElementById('modalRoot').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal wide"><h2>${isModify?'Modify DAM asset in Adobe GenStudio':'Create asset in Adobe GenStudio'}</h2><p>${isModify?'Update the approved content and provide instructions for how Adobe GenStudio should adapt this asset. The original DAM asset will remain the source and its lineage will be retained.':'Campaign Studio has pre-populated the request from the accepted campaign context.'}</p><div class="genstudio-context"><div class="genstudio-source-preview"><small>${isModify?'SOURCE · '+esc(a.id):'NEW ASSET REQUEST'}</small><strong>${esc(a.headline||a.requirement)}</strong><small style="margin-top:6px;opacity:.85">${esc(a.channel)} · ${esc(a.format)} · ${esc(a.dimensions)}</small><small style="opacity:.85">${esc(a.genStudioContext.lineage)}</small></div><div><div class="form-grid"><div class="field full"><label>Title</label><input id="gsTitle" value="${esc(isModify?'Discover what is possible with iPortal':'A step change in how you bank with Barclays')}"></div><div class="field full"><label>Description</label><textarea id="gsDescription">Discover a simpler way to manage your digital banking with iPortal.</textarea></div><div class="field full"><label>CTA</label><input id="gsCta" value="Discover iPortal"></div><div class="field full"><label>Prompt</label><textarea id="gsPrompt" style="min-height:140px">${isModify?'Retain the approved iPortal visual identity and flight-path visual device. Adapt the title, description and CTA for the Digital Adoption audience while preserving Barclays brand styling, accessibility requirements and the existing asset lineage.':'Create a new '+a.dimensions+' asset using the approved iPortal visual identity and flight-path visual device. Craft the title, description and CTA for the Digital Adoption audience while preserving Barclays brand styling, accessibility requirements and asset lineage.'}</textarea></div></div></div></div><div class="modal-actions"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="submitGenStudioAssetRequest(${i},'${mode}')">${isModify?'Modify in GenStudio':'Create in GenStudio'}</button></div></div></div>`;}
function submitGenStudioAssetRequest(i,mode){const a=state.assets[i];a.pendingRequest={title:document.getElementById('gsTitle').value,description:document.getElementById('gsDescription').value,cta:document.getElementById('gsCta').value,prompt:document.getElementById('gsPrompt').value};a.genStudioContext=Object.assign({sourceId:a.id,channel:a.channel,format:a.format,dimensions:a.dimensions},a.genStudioContext||{});closeModal();state.damGeneratingId=a.id;renderAll();setTimeout(()=>{const req=a.pendingRequest||{};a.sourceAssetId=mode==='modify'?a.id:null;a.jobId='GS-'+(mode==='modify'?'ADAPT':'CREATE')+'-'+String(Date.now()).slice(-5);a.headline=req.title||'Discover what is possible with iPortal';a.copy=req.description||'Bring payments, reporting and self-service together in one connected digital experience.';a.cta=req.cta||'Discover iPortal';a.genStudioPrompt=req.prompt||'';a.sourceType='Adobe GenStudio';a.found=true;a.generated=mode==='create';a.adapted=mode==='modify';a.previewType='generated';a.approval='Automated brand check passed';a.matchStatus=mode==='modify'?'Adapted in GenStudio':'New asset generated';a.confidence='Campaign-ready draft';a.matchReason='Adobe GenStudio applied the approved visual direction, audience message, target format and mandatory requirements.';a.included=false;state.damGeneratingId=null;addActivity(`${a.requirement} returned by Adobe GenStudio · ${a.jobId}`);renderAll();toast('Adobe GenStudio asset created');},5000);}
function generateMissing(){const i=state.assets.findIndex(x=>!x.found);if(i>=0)openGenStudioRequest(i,'create');else toast('No unresolved asset gaps remain');}
function renderOutputPreview(o){return o.channel==='Email'?`<div class="email-preview"><strong>${esc(o.headline)}</strong><p>${esc(o.body)}</p><p style="margin-top:8px"><strong>${esc(o.cta)} →</strong></p></div>`:`<div class="social-preview"><small>Sponsored · Barclays</small><h4>${esc(o.headline)}</h4><p>${esc(o.body)}</p><p style="margin-top:8px"><strong>${esc(o.cta)} →</strong></p></div>`;}
function renderOutputCard(key,o){const busy=state.outputGeneratingKey===key||state.outputSavingKey===key;return `<div class="output-card ${o.approved?'accepted':''}" id="output-card-${key}"><div class="output-card-head"><div><h4>${esc(o.label)} ${o.previousVersions.length?`<span class="previous-version-chip">${o.previousVersions.length} previous version${o.previousVersions.length===1?'':'s'}</span>`:''}</h4><p>Adobe GenStudio · Job ${esc(o.jobId)} · Draft v${o.version}.0</p></div><div style="display:flex;align-items:center;gap:7px"><span class="tag ${o.approved?'success':'blue'}">${o.approved?'Accepted':'Draft'}</span><button class="collaborator-trigger" onclick="openSubAssetComments(6,'${esc(o.commentsKey)}','${esc(o.label.replace(/'/g,"\\'"))}')"><span class="avatar-stack"><span>HM</span><span>AR</span></span><span class="comment-count">${(state.subAssetComments[o.commentsKey]||[]).length}</span></button></div></div><div class="output-card-body"><div class="output-preview-grid"><div class="asset-preview">${renderOutputPreview(o)}</div><div class="output-metadata"><div class="output-meta"><label>Audience</label><span>${esc(o.audience)}</span></div><div class="output-meta"><label>Format</label><span>${esc(o.format)} · ${esc(o.dimensions)}</span></div><div class="output-meta"><label>Source assets</label><span>${esc(o.sourceAssetIds.join(', '))}</span></div><div class="output-meta"><label>Visual direction</label><span>${esc(o.creativeRoute)}</span></div><div class="output-meta"><label>Tracking</label><span>${esc(o.tracking)}</span></div><div class="output-meta"><label>Accessibility</label><span>${esc(o.accessibility)}</span></div></div></div>${state.outputGeneratingKey===key?`<div class="genstudio-inline"><div class="genstudio-mark">Gs</div><div><strong>Adobe GenStudio is creating a revised version <span class="thinking-dots"><span></span><span></span><span></span></span></strong><span>Applying the revision request, preserving approved elements and checking copy, layout and accessibility.</span></div></div>`:''}${state.outputSavingKey===key?`<div class="output-save-state">Saving and registering the accepted ${esc(o.label)} <span class="thinking-dots"><span></span><span></span><span></span></span></div>`:''}</div><div class="output-card-actions"><button class="btn" ${busy?'disabled':''} onclick="openOutputEdit('${key}')">Edit</button><button class="btn" ${busy?'disabled':''} onclick="openOutputRevision('${key}')">Request changes</button><button class="btn" ${busy?'disabled':''} onclick="openOutputRevision('${key}')">Regenerate</button><button class="btn" onclick="previewOutput('${key}')">Preview</button><button class="btn primary" ${busy||o.approved?'disabled':''} onclick="acceptOutput('${key}')">${o.approved?'Accepted':'Accept output'}</button><button class="btn danger" ${busy?'disabled':''} onclick="excludeOutput('${key}')">${o.excluded?'Restore':'Exclude from launch'}</button></div></div>`;}
function renderOutputs(){const values=Object.entries(state.outputs).filter(([,o])=>!o.excluded),approved=values.filter(([,o])=>o.approved);return `${stageHeader(6,'Adobe GenStudio channel outputs','Campaign Studio sends the accepted brief, audiences, brief-level measurement and tracking requirements, production plan, selected assets, channel formats and mandatory-content requirements to Adobe GenStudio.')}<p class="answer-intro"><strong>Adobe GenStudio created the requested channel outputs.</strong> Each execution retains its selected source assets and the brief-led campaign proposition, while adapting copy, layout, tracking and accessibility for the channel.</p><div class="callout info"><div><strong>Context sent to Adobe GenStudio</strong><br>Accepted brief · selected segments · brief-level measurement and tracking requirements · production plan · selected DAM and GenStudio assets · mandatory language · tracking and accessibility requirements.</div></div><div class="artifact"><div class="artifact-head"><div class="artifact-title">${assetIconForStage(6)}Adobe GenStudio output package</div>${renderAssetHeaderRight(6,approved.length+' accepted')}</div><div class="artifact-body"><div class="output-list">${Object.entries(state.outputs).map(([k,o])=>renderOutputCard(k,o)).join('')}</div></div><div class="artifact-actions">${renderStandardAssetActions(6,'Accept '+approved.length+' accepted outputs',`acceptStageAsset(6,'Channel output package')`,`<button class="btn" onclick="toast('Accessibility and tracking comparison opened')">Review technical details</button>`)}</div></div>`;}
function openOutputEdit(key){const o=state.outputs[key];document.getElementById('modalRoot').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal wide"><h2>Edit ${esc(o.label)}</h2><p>Saving these changes creates a new draft version and preserves the current version in history.</p><div class="form-grid"><div class="field full"><label>Headline</label><input id="outHeadline" value="${esc(o.headline)}"></div><div class="field full"><label>Body copy</label><textarea id="outBody">${esc(o.body)}</textarea></div><div class="field"><label>CTA</label><input id="outCta" value="${esc(o.cta)}"></div><div class="field"><label>Tracking details</label><input id="outTracking" value="${esc(o.tracking)}"></div><div class="field full"><label>Accessibility text</label><textarea id="outAccessibility">${esc(o.accessibility)}</textarea></div></div><div class="modal-actions"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="submitOutputEdit('${key}')">Update</button></div></div></div>`;}
function submitOutputEdit(key){const request={headline:document.getElementById('outHeadline').value,body:document.getElementById('outBody').value,cta:document.getElementById('outCta').value,tracking:document.getElementById('outTracking').value,accessibility:document.getElementById('outAccessibility').value};closeModal();runOutputGenStudioRevision(key,request,'Direct edit submitted to Adobe GenStudio');}
function openOutputRevision(key){const o=state.outputs[key];document.getElementById('modalRoot').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal wide"><h2>Request changes from Adobe GenStudio</h2><p>${esc(o.label)} · Current draft v${o.version}.0</p><div class="genstudio-context"><div class="genstudio-source-preview"><small>CURRENT OUTPUT</small><strong>${esc(o.headline)}</strong></div><div class="form-grid"><div class="field full"><label>Requested change</label><textarea id="revisionRequest">Retain the current visual and CTA. Shorten the copy, make the headline more outcome-led and increase the prominence of the iPortal interface.</textarea></div><div class="field"><label>Elements to preserve</label><input id="preserveElements" value="Creative route, logo, CTA and approved product language"></div><div class="field"><label>Elements to modify</label><input id="modifyElements" value="Headline, body-copy length and interface prominence"></div><div class="field full"><label>Additional instructions</label><textarea id="revisionAdditional">Keep the output within the existing format and accessibility requirements.</textarea></div></div></div><div class="modal-actions"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="submitOutputRevision('${key}')">Send change request to Adobe GenStudio</button></div></div></div>`;}
function submitOutputRevision(key){const instruction=document.getElementById('revisionRequest').value;closeModal();const o=state.outputs[key];const request=key==='linkedin'?{headline:'One digital front door. More ways to get things done.',body:'Bring payments, reporting and self-service together with iPortal.',cta:o.cta}:{headline:'Do more digitally with iPortal',body:'Complete everyday banking and servicing tasks in one connected digital place.',cta:o.cta};runOutputGenStudioRevision(key,request,instruction);}
function runOutputGenStudioRevision(key,request,reason){if(state.outputGeneratingKey)return;const o=state.outputs[key];state.outputGeneratingKey=key;renderAll();setTimeout(()=>{o.previousVersions.unshift({version:o.version,headline:o.headline,body:o.body,cta:o.cta,jobId:o.jobId,reason});o.version+=1;o.headline=request.headline||o.headline;o.body=request.body||o.body;o.cta=request.cta||o.cta;o.tracking=request.tracking||o.tracking;o.accessibility=request.accessibility||o.accessibility;o.jobId='GS-'+key.toUpperCase()+'-'+String(Date.now()).slice(-5);o.approved=false;state.outputGeneratingKey=null;archiveDownstream(6,o.label+' regenerated in Adobe GenStudio');addActivity(`${o.label} v${o.version}.0 returned by Adobe GenStudio`);renderAll();toast('Revised Adobe GenStudio output returned');},5000);}
function acceptOutput(key){if(state.outputSavingKey||state.outputGeneratingKey)return;const o=state.outputs[key];state.outputSavingKey=key;renderAll();setTimeout(()=>{o.approved=true;o.excluded=false;o.acceptedAt='Registered just now';state.outputSavingKey=null;addActivity(`${o.label} accepted · v${o.version}.0`);renderAll();toast(o.label+' accepted');},2600);}
function excludeOutput(key){const o=state.outputs[key];o.excluded=!o.excluded;if(o.excluded)o.approved=false;archiveDownstream(6,'Channel output selection changed');renderAll();}
function previewOutput(key){const o=state.outputs[key];document.getElementById('modalRoot').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal wide"><h2>${esc(o.label)}</h2><p>Adobe GenStudio job ${esc(o.jobId)} · Draft v${o.version}.0</p><div class="asset-preview">${renderOutputPreview(o)}</div><div class="modal-actions"><button class="btn primary" onclick="closeModal()">Close preview</button></div></div></div>`;}
function toggleOutput(key){acceptOutput(key);}
function regenerateOutput(key){openOutputRevision(key);}
function renderLaunch(){const approved=Object.entries(state.outputs).filter(([,v])=>v.approved);return `${stageHeader(7,'Launch handoff and mock publish','The assistant assembles the final campaign pack, checks readiness and hands approved assets to destination systems.')}
 <p class="answer-intro">The campaign is ready to hand off with <strong>${approved.length} approved channel outputs</strong>, two selected audience cohorts, validated tracking requirements and a complete set of registered campaign records.</p>
 <div class="artifact"><div class="artifact-head"><div class="artifact-title">${assetIconForStage(7)}Launch readiness and destination handoff</div>${renderAssetHeaderRight(7,state.published?'Published':'Ready for decision')}</div><div class="artifact-body">
  <div class="table"><div class="tr head"><div>Readiness item</div><div>Result</div><div>Evidence</div><div>Status</div></div>
   <div class="tr"><div><strong>Audience lists</strong></div><div>${state.segments.filter(x=>x.selected).reduce((a,b)=>a+b.count,0).toLocaleString('en-GB')} CSIDs</div><div>Consent and eligibility rules</div><div class="row-status pass">Ready</div></div>
   <div class="tr"><div><strong>Final assets</strong></div><div>${approved.length} approved outputs</div><div>GenStudio approval record</div><div class="row-status pass">Ready</div></div>
   <div class="tr"><div><strong>Tracking</strong></div><div>UTM, source and CSID exposure</div><div>Measurement plan</div><div class="row-status pass">Ready</div></div>
   <div class="tr"><div><strong>Governance</strong></div><div>Accepted campaign records</div><div>Campaign Studio audit trail</div><div class="row-status pass">Ready</div></div>
  </div>
  <div class="answer-section"><h3>Destination systems</h3>${approved.map(([key,v])=>`<div class="destination"><div><strong>${esc(v.label)}</strong><div class="field-hint">${key==='email'?'ESP journey and CRM activation':'LinkedIn Campaign Manager'}</div></div><span class="row-status pass">${state.published?'✓ Pushed':'Queued'}</span></div>`).join('')}<div class="destination"><div><strong>GA4 and campaign dashboard</strong><div class="field-hint">Tracking configuration and reporting handoff</div></div><span class="row-status pass">${state.published?'✓ Configured':'Queued'}</span></div></div>
  ${state.published?`<div class="callout success">${ICON.check}<div><strong>Mock publish complete</strong><br>The final launch pack, destination status and audit trail are available for export.</div></div>`:`<div class="field"><label>Launch condition or note</label><textarea id="launchNote" placeholder="Optional condition for the launch record"></textarea></div>`}
 </div><div class="artifact-actions">${state.published?`<button class="btn" onclick="exportState()">Export campaign state</button><button class="btn" onclick="toast('Audit trail opened')">View audit trail</button>`:`<button class="btn" onclick="openAssetEditModal(7)">Edit</button><button class="btn" onclick="regenerateStageFromChat(7)">Regenerate</button><button class="btn" ${selectedCommentsForStage(7)?'':'disabled'} onclick="applyStageComments(7)">Generate with collaborator comments (${selectedCommentsForStage(7)})</button><button class="btn" onclick="holdLaunch()">Hold launch</button><button class="btn" onclick="publishCampaign(true)">Approve with conditions</button><button class="btn primary" onclick="publishCampaign(false)">Confirm publish</button>`}${renderInlineOperation(7)}</div></div>`;}
function holdLaunch(){addActivity('Launch placed on hold');toast('Launch held — return to channel outputs or an earlier asset to revise');}
function publishCampaign(conditional){if(state.generatingStage!==null||state.savingStage!==null)return;runAssetRegeneration(7,'Publishing campaign and finalising launch record',()=>{state.published=true;addActivity('Campaign pushed to mock destination systems'+(conditional?' with conditions':''));setTimeout(()=>beginAssetRegistration(7,'Launch handoff package'),0);});}
function exportState(){const blob=new Blob([JSON.stringify({campaignName:state.campaignName,objective:state.objective,briefSections,segments:state.segments,production:state.production,assets:state.assets,outputs:state.outputs,published:state.published,briefId:state.briefId,workflowVersion:state.workflowVersion,versionHistory:state.versionHistory},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='barclays-campaign-state.json';a.click();}


