const teamsState={
 generating:false,summaryReady:false,authorised:false,replyOpen:null,thinkingStep:0,
 thinkingStatuses:['Reviewing the team discussion…','Searching relevant Teams conversations…','Reviewing Outlook emails…','Reading related SharePoint documents…','Preparing the initial iPortal campaign brief…'],
 messages:[],typing:null,systemEventShown:false,agentIntroReady:false,acknowledgementReady:false,agentRecommendationReady:false,sequenceRunning:false,approvalInProgress:false,runId:0,reactionPulse:null,peopleOpen:false,activeParticipant:null,activeParticipantStatus:''
};
const teamsWait=ms=>new Promise(resolve=>setTimeout(resolve,ms));
function teamsRunCurrent(runId){return runId===teamsState.runId;}
function cloneTeamsValue(value){return JSON.parse(JSON.stringify(value));}
function teamsTypingDots(){return '<span class="teams-typing-dots"><i></i><i></i><i></i></span>';}
function teamsTypingCard(){const t=teamsState.typing;if(!t||t.kind!=='message')return '';const p=teamsParticipant(t.initials);return `<div class="teams-typing-card"><div class="teams-avatar ${p.type==='agent'?'agent':''}">${esc(p.initials)}</div><div class="teams-typing-copy"><strong>${esc(p.name)} is typing${teamsTypingDots()}</strong><span>${esc(p.role)}</span></div></div>`;}
function teamsReplyTyping(parentId){const t=teamsState.typing;if(!t||t.kind!=='reply'||t.parentId!==parentId)return '';const p=teamsParticipant(t.initials);return `<div class="teams-thread-typing"><div class="teams-avatar ${p.type==='agent'?'agent':''}">${esc(p.initials)}</div><div class="teams-thread-typing-copy"><strong>${esc(p.name)}</strong> is typing${teamsTypingDots()}</div></div>`;}
function renderTeamsPost(m){
 const profile=teamsParticipant(m.initials);
 if(m.agentRecommendation){return `<article class="teams-post agent-post teams-agent-recommendation-post"><div class="teams-post-top"><div class="teams-avatar agent">AI</div><div class="teams-author"><strong>${esc(profile.name)}</strong><span>${esc(profile.role)} · ${esc(m.time)}</span></div></div><div class="teams-agent-listening">Campaign opportunity identified</div>${renderTeamsRecommendation()}</article>`;}
 return `<article class="teams-post ${profile.type==='agent'?'agent-message':''} ${m.humanConfirmation?'teams-human-confirmation':''}"><div class="teams-post-top"><div class="teams-avatar ${profile.type==='agent'?'agent':''}">${esc(profile.initials)}</div><div class="teams-author"><strong>${esc(profile.name)}</strong><span>${esc(profile.role)} · ${esc(m.time)}</span></div></div><p>${esc(m.text)}</p><div class="teams-post-actions"><button class="teams-mini-action teams-reaction ${teamsState.reactionPulse===m.id?'teams-reaction-pop':''}" onclick="reactTeams('${m.id}')">👍 <span>${m.reactions||0}</span></button><button class="teams-mini-action" onclick="toggleTeamReply('${m.id}')">Reply</button><button class="teams-mini-action">•••</button></div>${m.replies&&m.replies.length||teamsState.typing&&teamsState.typing.kind==='reply'&&teamsState.typing.parentId===m.id?`<div class="teams-thread">${(m.replies||[]).map(r=>{const rp=teamsParticipant(r.initials);return `<div class="teams-reply"><div class="teams-avatar ${rp.type==='agent'?'agent':''}">${esc(rp.initials)}</div><div class="teams-reply-body"><strong>${esc(rp.name)}</strong>${esc(r.text)}<span>${esc(r.time)}</span></div></div>`;}).join('')}${teamsReplyTyping(m.id)}</div>`:''}${teamsState.replyOpen===m.id?`<div class="teams-inline-reply"><input id="teamReply-${m.id}" placeholder="Reply in this thread…"><button onclick="postTeamReply('${m.id}')">Reply</button></div>`:''}</article>`;
}
function teamsParticipantActivity(){
 if(teamsState.typing){const p=teamsParticipant(teamsState.typing.initials);return {initials:p.initials,status:teamsState.typing.kind==='reply'?'Replying in thread…':teamsState.typing.kind==='agent'?'Preparing a recommendation…':'Typing…'};}
 if(teamsState.generating)return {initials:'AI',status:teamsState.thinkingStatuses[teamsState.thinkingStep]};
 if(teamsState.summaryReady)return {initials:'AI',status:'Campaign brief prepared'};
 if(teamsState.agentRecommendationReady&&!teamsState.authorised)return {initials:'AI',status:'Waiting for team confirmation'};
 if(teamsState.activeParticipant)return {initials:teamsState.activeParticipant,status:teamsState.activeParticipantStatus||'Contributing…'};
 return null;
}
function renderTeamsPeople(){
 const panel=document.getElementById('teamsPeople');if(!panel)return;
 const active=teamsParticipantActivity();
 panel.classList.toggle('open',!!teamsState.peopleOpen);
 panel.innerHTML=`<div class="teams-people-head"><div><h3>People in this discussion</h3><div class="teams-people-count">${TEAMS_PARTICIPANTS.length} participants</div></div><button class="teams-people-close" onclick="toggleTeamsPeople(false)" aria-label="Close people panel">×</button></div>${TEAMS_PARTICIPANTS.map(p=>{const isActive=active&&active.initials===p.initials;const status=isActive?active.status:(p.initials==='AI'?(teamsState.summaryReady?'Campaign brief prepared':teamsState.generating?teamsState.thinkingStatuses[teamsState.thinkingStep]:teamsState.agentRecommendationReady&&!teamsState.authorised?'Waiting for team confirmation':'Following this channel'):p.defaultStatus);return `<div class="teams-person ${isActive?'active':''} ${p.type==='agent'?'agent-row':''}"><div class="teams-person-avatar-wrap"><div class="teams-avatar ${p.type==='agent'?'agent':''}">${esc(p.initials)}</div><span class="teams-person-presence-dot ${p.presence==='away'?'away':p.presence==='offline'?'offline':''}"></span></div><div class="teams-person-copy"><strong>${esc(p.name)}</strong><span class="teams-person-role">${esc(p.role)}</span><span class="teams-person-status">${esc(status)}</span></div><span class="teams-person-type"></span></div>`;}).join('')}`;
 const backdrop=document.getElementById('teamsPeopleBackdrop');if(backdrop)backdrop.classList.toggle('open',!!teamsState.peopleOpen);
}
function toggleTeamsPeople(force){teamsState.peopleOpen=typeof force==='boolean'?force:!teamsState.peopleOpen;renderTeamsPeople();}

function renderTeams(){
 const feed=document.getElementById('teamsFeedInner');if(!feed)return;
 const systemEvent=teamsState.systemEventShown?`<div class="teams-system-event"><span class="teams-system-event-icon">＋</span><span>Campaign Coordinator was added to the iPortal Adoption channel.</span><time>08:58</time></div>`:'';
 const posts=teamsState.messages.map(renderTeamsPost).join('');
 let dynamicAgent='';
 if(teamsState.generating){dynamicAgent=`<div class="teams-post agent-post agent-message"><div class="teams-post-top"><div class="teams-avatar agent">AI</div><div class="teams-author"><strong>Campaign Coordinator</strong><span>AI agent · creating campaign</span></div></div><div class="teams-thinking" style="margin:12px 0 0 41px"><div class="teams-thinking-copy">${esc(teamsState.thinkingStatuses[teamsState.thinkingStep])} <span class="thinking-dots"><span></span><span></span><span></span></span></div></div></div>`;}
 else if(teamsState.summaryReady){dynamicAgent=`<div class="teams-post agent-post agent-message"><div class="teams-post-top"><div class="teams-avatar agent">AI</div><div class="teams-author"><strong>Campaign Coordinator</strong><span>AI agent · campaign prepared</span></div></div>${renderTeamsSummary()}</div>`;}
 feed.innerHTML=systemEvent+posts+teamsTypingCard()+dynamicAgent;
 const chip=document.getElementById('teamsAgentChip');if(chip)chip.textContent=teamsState.generating?'Campaign Coordinator creating brief':teamsState.summaryReady?'Campaign brief prepared':teamsState.agentRecommendationReady&&!teamsState.authorised?'Campaign Coordinator awaiting approval':'Campaign Coordinator following channel';
 renderTeamsPeople();
 requestAnimationFrame(()=>{const c=document.getElementById('teamsFeed');if(c)c.scrollTo({top:c.scrollHeight,behavior:'smooth'});});
}
function renderTeamsRecommendation(){return `<p class="teams-opportunity-intro">Based on the discussion, this looks like a strong candidate for a targeted iPortal adoption campaign.</p><div class="teams-opportunity-compact"><div class="teams-opportunity-row"><strong>Challenge</strong><span>Clients are underusing available iPortal self-service capabilities.</span></div><div class="teams-opportunity-row"><strong>Audience</strong><span>Servicing-heavy, digitally dormant and advanced digital-user cohorts.</span></div><div class="teams-opportunity-row"><strong>Opportunity</strong><span>Improve awareness, first meaningful use and deeper feature adoption.</span></div><div class="teams-opportunity-row"><strong>Open questions</strong><span>Adoption baseline, eligible population, consent and claims evidence.</span></div></div><div class="teams-agent-question compact"><strong>Would you like me to create it?</strong>I can use this discussion and the connected sources to create a Campaign Studio workspace and prepare an initial campaign brief.</div><div class="teams-agent-actions"><button class="teams-agent-primary" onclick="approveCampaignCreation()">Yes, create the campaign brief</button><button class="teams-agent-secondary" onclick="useTeamsPrompt()">Draft a response</button></div><div class="teams-reading-note">Waiting for the team’s confirmation</div>`;}
function renderTeamsSummary(){return `<p>Thanks, Sarah. I reviewed the discussion, searched the connected sources and created the initial Campaign Studio workspace and campaign brief.</p><div class="teams-summary-card"><div class="teams-summary-head"><strong>iPortal campaign workspace</strong><span>Initial campaign brief prepared</span></div><div class="teams-summary-body"><div class="teams-summary-grid"><div class="teams-summary-item"><label>Proposed campaign</label><div>iPortal Digital Engagement Campaign</div></div><div class="teams-summary-item"><label>Problem statement</label><div>Clients are not consistently discovering or using existing self-service capabilities.</div></div><div class="teams-summary-item"><label>Commercial objective</label><div>Improve awareness, first meaningful use and feature adoption across priority cohorts.</div></div><div class="teams-summary-item"><label>Audience considerations</label><div>Servicing-heavy users, digitally dormant clients and advanced digital users.</div></div><div class="teams-summary-item"><label>Sources reviewed</label><div>Teams discussion, Outlook roadmap review and SharePoint campaign documents.</div></div><div class="teams-summary-item"><label>Evidence gaps</label><div>Current active-user baseline and eligible population still require validation.</div></div></div><button class="teams-open-brief" onclick="openCampaignStudioFromTeams()"><span>Open the generated iPortal campaign brief</span><span>→</span></button></div></div>`;}
async function showTeamsScriptItem(item,runId,first=false){
 if(!first){await teamsWait(1500);if(!teamsRunCurrent(runId))return false;}
 if(item.type==='reaction'){
  const m=teamsState.messages.find(x=>x.id===item.parentId);if(m){m.reactions=item.count;teamsState.reactionPulse=m.id;renderTeams();await teamsWait(700);teamsState.reactionPulse=null;renderTeams();}return teamsRunCurrent(runId);
 }
 if(item.type==='message')teamsState.typing={kind:'message',initials:item.message.initials,name:item.message.name,role:item.message.role};
 if(item.type==='reply')teamsState.typing={kind:'reply',parentId:item.parentId,initials:item.reply.initials,name:item.reply.name,role:item.reply.role};
 renderTeams();await teamsWait(2000);if(!teamsRunCurrent(runId))return false;
 teamsState.typing=null;
 if(item.type==='message'){teamsState.messages.push(cloneTeamsValue(item.message));teamsState.activeParticipant=item.message.initials;teamsState.activeParticipantStatus='Contributing to the discussion…';}
 if(item.type==='reply'){const m=teamsState.messages.find(x=>x.id===item.parentId);if(m)m.replies.push(cloneTeamsValue(item.reply));teamsState.activeParticipant=item.reply.initials;teamsState.activeParticipantStatus='Replying in thread…';}
 renderTeams();return true;
}
async function runTeamsConversationSequence(){
 if(teamsState.sequenceRunning||teamsState.summaryReady)return;
 const runId=++teamsState.runId;teamsState.sequenceRunning=true;
 teamsState.systemEventShown=true;teamsState.activeParticipant='AI';teamsState.activeParticipantStatus='Added to channel';renderTeams();
 await teamsWait(1500);if(!teamsRunCurrent(runId))return;
 teamsState.typing={kind:'message',initials:'AI',name:'Campaign Coordinator',role:'AI agent'};renderTeams();
 await teamsWait(2000);if(!teamsRunCurrent(runId))return;
 teamsState.typing=null;teamsState.messages.push({id:'agent-intro',initials:'AI',name:'Campaign Coordinator',role:'AI agent',time:'08:59',text:'Hi everyone. I’ve been added to this channel to help capture the campaign context and turn the discussion into a structured campaign brief if needed. I’ll follow the conversation, retain the important decisions and evidence gaps, and step in once there is enough context.',reactions:0,replies:[]});teamsState.agentIntroReady=true;teamsState.activeParticipant='AI';teamsState.activeParticipantStatus='Following this channel';renderTeams();
 await teamsWait(1800);if(!teamsRunCurrent(runId))return;
 for(let i=0;i<TEAMS_DISCUSSION.length;i++){if(!await showTeamsScriptItem(TEAMS_DISCUSSION[i],runId,i===0))return;}
 await teamsWait(2000);if(!teamsRunCurrent(runId))return;
 teamsState.typing={kind:'message',initials:'AI',name:'Campaign Coordinator',role:'AI agent'};teamsState.activeParticipant='AI';teamsState.activeParticipantStatus='Preparing a recommendation…';renderTeams();
 await teamsWait(2600);if(!teamsRunCurrent(runId))return;
 teamsState.typing=null;teamsState.messages.push({id:'agent-recommendation',initials:'AI',name:'Campaign Coordinator',role:'AI agent',time:'09:36',agentRecommendation:true,reactions:0,replies:[]});teamsState.agentRecommendationReady=true;teamsState.activeParticipant='AI';teamsState.activeParticipantStatus='Waiting for team confirmation';renderTeams();
 await teamsWait(5000);if(!teamsRunCurrent(runId)||teamsState.authorised)return;
 await queueSarahApproval(false,runId);
}
async function queueSarahApproval(fromUser=false,runId=teamsState.runId){
 if(teamsState.authorised||teamsState.approvalInProgress||teamsState.generating||teamsState.summaryReady||!teamsState.agentRecommendationReady)return;
 teamsState.approvalInProgress=true;
 if(!fromUser){teamsState.typing={kind:'message',initials:'SC',name:'Sarah Chen',role:'Campaign Manager'};teamsState.activeParticipant='SC';teamsState.activeParticipantStatus='Typing…';renderTeams();await teamsWait(2200);if(!teamsRunCurrent(runId)||teamsState.authorised){teamsState.typing=null;teamsState.approvalInProgress=false;renderTeams();return;}teamsState.typing=null;}
 if(!fromUser)teamsState.messages.push({id:'approval-'+Date.now(),initials:'SC',name:'Sarah Chen',role:'Campaign Manager',time:'09:38',text:'Yes, please go ahead. Use this discussion as the starting context, and also review the relevant Teams conversations, Outlook emails and SharePoint documents before creating the initial iPortal campaign brief.',reactions:1,replies:[],humanConfirmation:true});teamsState.authorised=true;teamsState.approvalInProgress=false;teamsState.activeParticipant='SC';teamsState.activeParticipantStatus='Authorising campaign creation…';renderTeams();
 await teamsWait(1000);if(!teamsRunCurrent(runId))return;
 teamsState.typing={kind:'message',initials:'AI',name:'Campaign Coordinator',role:'AI agent'};teamsState.activeParticipant='AI';teamsState.activeParticipantStatus='Acknowledging request…';renderTeams();
 await teamsWait(1600);if(!teamsRunCurrent(runId))return;
 teamsState.typing=null;teamsState.messages.push({id:'agent-ack',initials:'AI',name:'Campaign Coordinator',role:'AI agent',time:'09:39',text:'Understood. I’ll review the discussion and connected sources, then prepare the initial brief.',reactions:0,replies:[]});teamsState.acknowledgementReady=true;renderTeams();
 await teamsWait(700);if(teamsRunCurrent(runId))startTeamsCreation();
}
function isCampaignApproval(text){return /\b(yes|go ahead|please proceed|proceed|create it|create the campaign|create the brief|prepare the brief|authorise|authorize)\b/i.test(text);}
function sendTeamsMessage(){const input=document.getElementById('teamsComposer'),text=input?input.value.trim():'';if(!text||teamsState.generating)return;const approval=teamsState.agentRecommendationReady&&isCampaignApproval(text);teamsState.messages.push({id:'m'+Date.now(),initials:'SC',name:'Sarah Chen',role:'Campaign Manager',time:'Just now',text,reactions:0,replies:[],humanConfirmation:approval});input.value='';teamsState.activeParticipant='SC';teamsState.activeParticipantStatus=approval?'Authorising campaign creation…':'Contributing to the discussion…';if(approval){teamsState.typing=null;teamsState.approvalInProgress=false;renderTeams();queueSarahApproval(true,teamsState.runId);}else renderTeams();}
function useTeamsPrompt(){const input=document.getElementById('teamsComposer');input.value='Yes, please go ahead. Use this discussion as the starting context, and also review the relevant Teams conversations, Outlook emails and SharePoint documents before creating the initial iPortal campaign brief.';input.focus();}
function approveCampaignCreation(){queueSarahApproval(false,teamsState.runId);}
function reactTeams(id){const m=teamsState.messages.find(x=>x.id===id);if(m)m.reactions=(m.reactions||0)+1;teamsState.reactionPulse=id;renderTeams();setTimeout(()=>{teamsState.reactionPulse=null;renderTeams();},350);}
function toggleTeamReply(id){teamsState.replyOpen=teamsState.replyOpen===id?null:id;renderTeams();setTimeout(()=>{const el=document.getElementById('teamReply-'+id);if(el)el.focus();},30);}
function postTeamReply(id){const input=document.getElementById('teamReply-'+id),text=input?input.value.trim():'';if(!text)return;const m=teamsState.messages.find(x=>x.id===id);if(m){if(!m.replies)m.replies=[];m.replies.push({initials:'SC',name:'Sarah Chen',role:'Campaign Manager',time:'Just now',text});}teamsState.activeParticipant='SC';teamsState.activeParticipantStatus='Replying in thread…';teamsState.replyOpen=null;if(teamsState.agentRecommendationReady&&isCampaignApproval(text)){renderTeams();queueSarahApproval(true,teamsState.runId);}else renderTeams();}
async function startTeamsCreation(){
 if(teamsState.generating||teamsState.summaryReady||!teamsState.authorised)return;
 const runId=teamsState.runId;teamsState.generating=true;teamsState.thinkingStep=0;teamsState.activeParticipant='AI';teamsState.activeParticipantStatus=teamsState.thinkingStatuses[0];renderTeams();
 for(let i=1;i<teamsState.thinkingStatuses.length;i++){await teamsWait(1000);if(!teamsRunCurrent(runId)||!teamsState.generating)return;teamsState.thinkingStep=i;renderTeams();}
 await teamsWait(1000);if(!teamsRunCurrent(runId)||!teamsState.generating)return;teamsState.generating=false;teamsState.summaryReady=true;teamsState.sequenceRunning=false;renderTeams();
}
function replayTeamsDiscussion(){teamsState.runId+=1;teamsState.generating=false;teamsState.summaryReady=false;teamsState.authorised=false;teamsState.replyOpen=null;teamsState.thinkingStep=0;teamsState.messages=[];teamsState.typing=null;teamsState.systemEventShown=false;teamsState.agentIntroReady=false;teamsState.acknowledgementReady=false;teamsState.agentRecommendationReady=false;teamsState.sequenceRunning=false;teamsState.approvalInProgress=false;teamsState.reactionPulse=null;teamsState.peopleOpen=false;teamsState.activeParticipant=null;teamsState.activeParticipantStatus='';renderTeams();setTimeout(runTeamsConversationSequence,500);}
function openCampaignStudioFromTeams(){if(!teamsState.summaryReady){toast('Wait for the Campaign Coordinator to finish preparing the brief');return;}const teams=document.getElementById('teamsExperience'),app=document.getElementById('appRoot');teams.style.display='none';app.classList.remove('studio-hidden');app.classList.remove('not-started');state.started=true;state.initialPrompt='Create the iPortal Digital Engagement Campaign brief from the working-group discussion, relevant Teams conversations, Outlook emails and SharePoint documents.';state.sourceSearchComplete=true;state.completed.add(0);state.stage=1;state.focusStage=1;state.generatedAssets[1]=true;state.stagePrompts[1]=state.initialPrompt;state.activities.unshift('Campaign Studio workspace created from the team discussion and grounded Teams, Outlook and SharePoint sources');renderAll({scrollToStage:1});setTimeout(()=>{const el=document.getElementById('conversation-stage-1');if(el)el.scrollIntoView({behavior:'smooth',block:'start'});},80);}
function returnToTeams(){document.getElementById('appRoot').classList.add('studio-hidden');document.getElementById('teamsExperience').style.display='grid';renderTeams();}

