state.approval=false;
state.externalReviewer={id:'emma-lewis',initials:'EL',name:'Emma Lewis',role:'Creative Director · External Agency'};
state.assets.forEach(a=>Object.assign(a,{version:a.version||1,externalApprovalStatus:a.externalApprovalStatus||'Not requested',externalReviewerId:null,externalApprovalRequestedAt:null,externalApprovalCompletedAt:null,externalApprovedVersion:null,agencyTyping:false}));
Object.values(state.outputs).forEach(o=>Object.assign(o,{externalApprovalStatus:o.externalApprovalStatus||'Not requested',externalReviewerId:null,externalApprovalRequestedAt:null,externalApprovalCompletedAt:null,externalApprovedVersion:null,agencyTyping:false}));
if(!state.subAssetComments['dam-email'].some(c=>c.initials==='EL'))state.subAssetComments['dam-email'].push({initials:'EL',name:'Emma Lewis',role:'Creative Director · External Agency',time:'Available',location:'External creative review',text:'Tag me when the adapted version is ready and I can review channel fit, hierarchy and final export quality.',selected:false,incorporated:false,replies:[]});
if(!state.subAssetComments['output-linkedin'].some(c=>c.initials==='EL'))state.subAssetComments['output-linkedin'].push({initials:'EL',name:'Emma Lewis',role:'Creative Director · External Agency',time:'Available',location:'External creative review',text:'I can review this output once the campaign team sends the current version for agency approval.',selected:false,incorporated:false,replies:[]});

function nextPromptDescription(i){const current=state.acceptedAssets[i];if(i===1)return `Brief <strong>${esc(current.id)}</strong> is registered. I can now translate the accepted business need, eligibility rules and channel constraints into deterministic audience segments.`;if(i===2)return `Segment set <strong>${esc(current.id)}</strong> is registered. I can now assemble the accepted brief, selected audiences, evidence gaps and conditions into the human approval package.`;if(i===3)return `Approval record <strong>${esc(current.id)}</strong> is registered. I can now convert the approved brief and audience decisions into channel production work packages.`;if(i===4)return `Production plan <strong>${esc(current.id)}</strong> is registered. I can now search Adobe DAM for reusable assets, adaptation candidates and missing formats.`;if(i===5)return `Asset selection package <strong>${esc(current.id)}</strong> is registered. I can now send the approved context and selected assets to Adobe GenStudio to create channel-ready outputs.`;if(i===6)return `Channel output package <strong>${esc(current.id)}</strong> is registered. I can now prepare the final audience, asset, agency-approval, tracking and destination handoff.`;return `Asset <strong>${esc(current.id)}</strong> is registered. The campaign workflow is complete.`;}

function renderApproval(){const selected=commentsForStage(3).filter(c=>c.selected&&!c.incorporated).length;const segs=state.segments.filter(s=>s.selected).map(s=>s.name).join(', ');return `${stageHeader(3,'Brief approval','The Marketing Strategy & Campaign Brief Agent packages the accepted brief and segment decisions for human governance in Adobe Workfront.')}<p class="answer-intro">The approval package is ready. It keeps the campaign opportunity, selected cohorts, source lineage and unresolved evidence gaps visible so the human approvers can make a conditioned decision.</p><div class="artifact"><div class="artifact-head"><div class="artifact-title">${assetIconForStage(3)}Campaign brief approval package</div>${renderAssetHeaderRight(3,state.approval?'Approved':'Awaiting approval')}</div><div class="artifact-body"><div class="approval-summary-grid"><div class="approval-summary-item"><label>Campaign objective</label><span>Increase awareness, first meaningful use and deeper iPortal adoption.</span></div><div class="approval-summary-item"><label>Accepted brief</label><span>${esc(state.briefId||'Campaign brief accepted')}</span></div><div class="approval-summary-item"><label>Selected cohorts</label><span>${esc(segs||'No cohorts selected')}</span></div><div class="approval-summary-item"><label>Channels</label><span>${esc(state.channels.join(' · '))}</span></div><div class="approval-summary-item"><label>Budget and timing</label><span>£310,102 · September launch · phased activation</span></div><div class="approval-summary-item"><label>Source lineage</label><span>Teams discussion · Outlook roadmap review · SharePoint campaign documents</span></div></div><div class="callout warning">${ICON.warn}<div><strong>Approval conditions</strong><br>Validate the active-user baseline and eligible population; retain consent, claims evidence and local-market coordination as explicit conditions.</div></div><div class="table"><div class="tr head"><div>Approver</div><div>Responsibility</div><div>Decision</div><div>Status</div></div><div class="tr"><div><strong>James Okonkwo</strong></div><div>Campaign owner</div><div>Strategy, scope and investment</div><div class="row-status ${state.approval?'pass':'flag'}">${state.approval?'Approved':'Pending'}</div></div><div class="tr"><div><strong>Helen Marsh</strong></div><div>Brand lead</div><div>Evidence gaps and mandatory constraints</div><div class="row-status ${state.approval?'pass':'flag'}">${state.approval?'Approved with conditions':'Pending'}</div></div></div></div><div class="artifact-actions"><button class="btn" onclick="openAssetEditModal(3)">Edit</button><button class="btn" onclick="regenerateStageFromChat(3)">Regenerate</button><button class="btn" ${selected?'':'disabled'} onclick="applyStageComments(3)">Generate with collaborator comments (${selected})</button><button class="btn primary" ${state.approval||state.savingStage===3?'disabled':''} onclick="openBriefApprovalModal()">${state.approval?'Approved':'Route and approve in Workfront'}</button>${renderInlineOperation(3)}</div></div>`;}
function openBriefApprovalModal(){document.getElementById('modalRoot').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal"><h2>Route the brief approval package</h2><p>Campaign Studio will create the Workfront approval record and retain the accepted brief, selected audiences, sources and open conditions.</p><div class="field"><label>Campaign owner</label><select><option>James Okonkwo — Head of GTB</option></select></div><div class="field"><label>Brand reviewer</label><select><option>Helen Marsh — Brand Lead</option></select></div><div class="field"><label>Approval decision</label><select id="approvalDecision"><option value="conditional">Approve with conditions</option><option value="approve">Approve</option></select></div><div class="field"><label>Conditions</label><textarea id="approvalConditions">Proceed subject to validation of the active-user baseline, eligible population, consent basis and supporting evidence for quantified claims.</textarea></div><div class="modal-actions"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="submitBriefApproval()">Create approval record</button></div></div></div>`;}
function submitBriefApproval(){const decision=document.getElementById('approvalDecision')?.value||'conditional';state.approval=true;closeModal();addActivity('Brief approval submitted in Adobe Workfront'+(decision==='conditional'?' with conditions':''));beginAssetRegistration(3,'Brief approval package');}
function renderStage(i){return [renderInput,renderBrief,renderSegments,renderApproval,renderProduction,renderAssets,renderOutputs,renderLaunch][i]();}

function renderProduction(){const active=state.production.filter(x=>!x.removed);return `${stageHeader(4,'Production plan','The Marketing Strategy & Campaign Brief Agent converts the approved brief, selected audiences and approval conditions into channel-specific work packages.')}<p class="answer-intro">The approved campaign record produces <strong>${active.length} production work packages</strong>. Each work package is tied to an audience, channel requirement, owner, timing, mandatory constraints and tracking dependency.</p><div class="artifact"><div class="artifact-head"><div class="artifact-title">${assetIconForStage(4)}Channel production work packages</div>${renderAssetHeaderRight(4,active.length+' active assets')}</div><div class="artifact-body">${state.production.map((p,i)=>`<div class="message-card ${p.removed?'':'selected'}" style="${p.removed?'opacity:.45':''}"><div style="display:flex;justify-content:space-between;gap:10px"><div><h4>${esc(p.channel)} · ${esc(p.asset)}</h4><p><strong>Audience:</strong> ${esc(p.audience)}</p><p><strong>Requirement:</strong> ${esc(p.message)}</p><p><strong>Format:</strong> ${esc(p.format)}</p><div class="tag-row"><span class="tag blue">${esc(p.owner)}</span><span class="tag">${esc(p.timing)}</span></div></div><button class="btn danger" onclick="toggleProduction(${i})">${p.removed?'Restore':'Remove'}</button></div></div>`).join('')}</div><div class="artifact-actions">${renderStandardAssetActions(4,'Accept production plan',`acceptStageAsset(4,'Production plan')`,`<button class="btn" onclick="toast('Workfront work packages created')">Create Workfront tasks</button>`)}</div></div>`;}

function externalItem(kind,key){return kind==='asset'?state.assets[Number(key)]:state.outputs[key];}
function externalCommentsKey(kind,key){const item=externalItem(kind,key);return item?.commentsKey;}
function externalStatusMarkup(item){if(!item)return '';const status=item.externalApprovalStatus||'Not requested';const approved=/^Approved/.test(status);const waiting=/Preparing|Sent|Awaiting|Reapproval/.test(status);return `<div class="external-approval ${approved?'approved':waiting?'waiting':''}"><div><strong>${approved?'External agency approval complete':'External agency review'}</strong><span>${esc(status)}${item.externalApprovedVersion?` · v${item.externalApprovedVersion}.0`:''}${item.externalApprovalCompletedAt?` · ${esc(item.externalApprovalCompletedAt)}`:''}</span></div><span class="external-badge">EL · External Agency</span></div>${item.agencyTyping?`<div class="agency-typing"><div class="agency-avatar">EL</div><div><strong>Emma Lewis is typing</strong><br>Reviewing creative quality, channel suitability and final export requirements <span class="thinking-dots"><span></span><span></span><span></span></span></div></div>`:''}`;}
function openExternalApprovalRequest(kind,key){const item=externalItem(kind,key);if(!item)return;document.getElementById('modalRoot').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal wide"><h2>Send for external agency approval</h2><p>${esc(item.name||item.label)} · ${kind==='asset'?'Asset':'Channel output'} version ${item.version||1}.0</p><div class="form-grid"><div class="field"><label>Agency reviewer</label><select id="agencyReviewer"><option>Emma Lewis — Creative Director · External Agency</option></select></div><div class="field"><label>Requested timing</label><select><option>Review today</option><option>Within 2 business days</option></select></div><div class="field full"><label>Approval request</label><textarea id="agencyRequest">@Emma Lewis Please review this asset for creative quality, channel suitability and alignment with the approved campaign brief. Add comments or approve the current version.</textarea></div><div class="field full"><label>Review areas</label><textarea>Visual hierarchy, format suitability, CTA prominence, interface legibility and final export quality.</textarea></div></div><div class="modal-actions"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="sendForExternalApproval('${kind}','${key}')">Send for approval</button></div></div></div>`;}
function sendForExternalApproval(kind,key){const item=externalItem(kind,key);if(!item)return;closeModal();item.externalApprovalStatus='Preparing request';item.externalReviewerId='emma-lewis';item.externalApprovalRequestedAt='Just now';item.agencyTyping=false;renderAll();setTimeout(()=>{item.externalApprovalStatus='Awaiting approval';item.agencyTyping=true;renderAll();setTimeout(()=>{item.agencyTyping=false;item.externalApprovalStatus='Approved with comments';item.externalApprovalCompletedAt='Just now';item.externalApprovedVersion=item.version||1;const ckey=externalCommentsKey(kind,key);if(ckey){if(!state.subAssetComments[ckey])state.subAssetComments[ckey]=[];state.subAssetComments[ckey].push({initials:'EL',name:'Emma Lewis',role:'Creative Director · External Agency',time:'Just now',location:'External agency approval',text:'I reviewed the current version. The visual hierarchy and channel format work well. Please retain the approved CTA and ensure the product interface remains legible at the final export size.',selected:false,incorporated:false,replies:[{initials:'SC',name:'Sarah Chen',time:'Just now',owner:true,text:'Thanks, Emma. We will retain the CTA and check the interface crop before final export.'},{initials:'EL',name:'Emma Lewis',time:'Just now',owner:false,text:'That works for us. Please send the updated version when ready.'}]});}addActivity(`${item.name||item.label} approved with comments by Emma Lewis · External Agency`);renderAll();toast('External agency approval returned');},2100);},2500);}
function resetExternalApproval(item){if(!item)return;item.externalApprovalStatus='Reapproval required';item.externalApprovedVersion=null;item.externalApprovalCompletedAt=null;item.agencyTyping=false;}
function renderDamResult(a,i){const selected=a.included,created=a.generated||a.adapted,statusClass=a.matchStatus==='Reusable'?'success':'warning';return `<div class="dam-result ${selected?'selected':''}" id="dam-result-${i}"><div class="dam-result-head">${damPreview(a)}<div class="dam-result-title"><h4>${esc(a.requirement)}</h4><p>${esc(a.name)} · ${esc(a.id)}</p><div class="tag-row"><span class="tag ${statusClass}">${esc(a.matchStatus)}</span><span class="adobe-source-label">${a.sourceType==='Requirement'?'Adobe DAM search':'Adobe '+esc(a.sourceType.replace('Adobe ',''))}</span><span class="tag blue">Match ${esc(a.confidence)}</span></div></div><div class="dam-result-tools"><button class="collaborator-trigger" onclick="openSubAssetComments(5,'${esc(a.commentsKey)}','${esc(a.requirement.replace(/'/g,"\\'"))}')"><span class="avatar-stack"><span>LN</span><span>EL</span><span>+1</span></span><span class="comment-count">${(state.subAssetComments[a.commentsKey]||[]).length}</span></button></div></div><div class="dam-result-body"><div class="dam-meta-grid"><div class="dam-meta"><label>Channel / format</label><span>${esc(a.channel)} · ${esc(a.format)}</span></div><div class="dam-meta"><label>Dimensions</label><span>${esc(a.dimensions)}</span></div><div class="dam-meta"><label>Approval</label><span>${esc(a.approval)}</span></div><div class="dam-meta"><label>Rights / expiry</label><span>${esc(a.rights)} · ${esc(a.expiry)}</span></div></div><p class="dam-rationale"><strong>Why this result:</strong> ${esc(a.matchReason)}</p><div class="lineage"><strong>Lineage:</strong><span>${a.adapted?`Adobe DAM ${esc(a.sourceAssetId||a.id)} → Adobe GenStudio ${esc(a.jobId)}`:a.generated?`Adobe GenStudio · ${esc(a.jobId)}`:a.found?`Adobe DAM · ${esc(a.id)}`:'Campaign requirement · no DAM match'}</span></div>${state.damGeneratingId===a.id?`<div class="genstudio-inline"><div class="genstudio-mark">Gs</div><div><strong>${a.found?'Adapting the selected DAM asset':'Creating the missing asset'} <span class="thinking-dots"><span></span><span></span><span></span></span></strong><span>Sending the brief-led request to Adobe GenStudio and checking channel-format requirements.</span></div></div>`:''}${created?`<div class="created-asset-preview"><strong>${a.adapted?'Adapted asset returned by Adobe GenStudio':'New asset returned by Adobe GenStudio'}</strong><p>${esc(a.headline)} · ${esc(a.dimensions)} · Job ${esc(a.jobId)}</p><div class="asset-preview"><div class="social-preview"><small>${esc(a.channel)} · Adobe GenStudio</small><h4>${esc(a.headline)}</h4><p>${esc(a.copy)}</p><p style="margin-top:8px"><strong>${esc(a.cta)} →</strong></p></div></div><p>Review, collaborate and select the asset if it is suitable for the campaign.</p></div>`:''}${externalStatusMarkup(a)}<div class="dam-result-actions"><label class="asset-choice"><input type="checkbox" ${selected?'checked':''} onchange="toggleAsset(${i})">Select for campaign</label>${a.found&&!a.generated?`<button class="btn" onclick="previewDamAsset(${i})">Preview asset</button><button class="btn" onclick="openGenStudioRequest(${i},'modify')">Modify in Adobe GenStudio</button>`:`${!created?`<button class="btn primary" onclick="openGenStudioRequest(${i},'create')">Create in Adobe GenStudio</button>`:`<button class="btn" onclick="openGenStudioRequest(${i},'create')">Request another version</button>`}`}${created?`<button class="btn" onclick="openExternalApprovalRequest('asset','${i}')">Send for agency approval</button>`:''}</div></div></div>`;}
function renderAssets(){const selected=state.assets.filter(x=>x.included),reusable=state.assets.filter(x=>x.matchStatus==='Reusable').length,adapt=state.assets.filter(x=>x.matchStatus==='Adaptation recommended').length,gaps=state.assets.filter(x=>x.matchStatus.includes('No suitable')).length;return `${stageHeader(5,'Adobe DAM search and asset selection','The Marketing Strategy & Campaign Brief Agent compares Adobe DAM content with the accepted brief, selected audiences, approval conditions, production requirements and channel formats.')}<p class="answer-intro">I searched <strong>Adobe DAM</strong> using the accepted campaign brief, audience decisions, approval record, production specifications and required channel formats. I reviewed 46 assets and returned reuse, adaptation and creation recommendations.</p><div class="adobe-search-summary"><div class="adobe-summary-metric"><span>DAM assets reviewed</span><strong>46</strong></div><div class="adobe-summary-metric"><span>Reusable matches</span><strong>${reusable}</strong></div><div class="adobe-summary-metric"><span>Adaptation candidates</span><strong>${adapt}</strong></div><div class="adobe-summary-metric"><span>Asset gaps</span><strong>${gaps}</strong></div></div>${renderDamCriteria()}<div class="artifact"><div class="artifact-head"><div class="artifact-title">${assetIconForStage(5)}Adobe DAM recommendations and GenStudio requests</div>${renderAssetHeaderRight(5,selected.length+' selected')}</div><div class="artifact-body"><div class="dam-result-list">${state.assets.map(renderDamResult).join('')}</div></div><div class="artifact-actions">${renderStandardAssetActions(5,'Accept '+selected.length+' selected assets',`acceptStageAsset(5,'Asset-selection package')`,`<button class="btn" onclick="toggleDamCriteria()">${state.damCriteriaOpen?'Hide':'View'} search evidence</button>`)}</div></div>`;}

function renderOutputCard(key,o){const busy=state.outputGeneratingKey===key||state.outputSavingKey===key;return `<div class="output-card ${o.approved?'accepted':''}" id="output-card-${key}"><div class="output-card-head"><div><h4>${esc(o.label)} ${o.previousVersions.length?`<span class="previous-version-chip">${o.previousVersions.length} previous version${o.previousVersions.length===1?'':'s'}</span>`:''}</h4><p>Adobe GenStudio · Job ${esc(o.jobId)} · Draft v${o.version}.0</p></div><div style="display:flex;align-items:center;gap:7px"><span class="tag ${o.approved?'success':'blue'}">${o.approved?'Accepted':'Draft'}</span><button class="collaborator-trigger" onclick="openSubAssetComments(6,'${esc(o.commentsKey)}','${esc(o.label.replace(/'/g,"\\'"))}')"><span class="avatar-stack"><span>HM</span><span>EL</span><span>+1</span></span><span class="comment-count">${(state.subAssetComments[o.commentsKey]||[]).length}</span></button></div></div><div class="output-card-body"><div class="output-preview-grid"><div class="asset-preview">${renderOutputPreview(o)}</div><div class="output-metadata"><div class="output-meta"><label>Audience</label><span>${esc(o.audience)}</span></div><div class="output-meta"><label>Format</label><span>${esc(o.format)} · ${esc(o.dimensions)}</span></div><div class="output-meta"><label>Source assets</label><span>${esc(o.sourceAssetIds.join(', '))}</span></div><div class="output-meta"><label>Visual direction</label><span>${esc(o.creativeRoute)}</span></div><div class="output-meta"><label>Tracking</label><span>${esc(o.tracking)}</span></div><div class="output-meta"><label>Accessibility</label><span>${esc(o.accessibility)}</span></div></div></div>${state.outputGeneratingKey===key?`<div class="genstudio-inline"><div class="genstudio-mark">Gs</div><div><strong>Adobe GenStudio is creating a revised version <span class="thinking-dots"><span></span><span></span><span></span></span></strong><span>The current version remains visible while copy, layout and channel requirements are applied.</span></div></div>`:''}${state.outputSavingKey===key?`<div class="asset-saving-state"><div class="asset-saving-spinner"></div><div class="asset-saving-copy"><strong>Saving the accepted ${esc(o.label)}…</strong><span>Registering output version ${o.version}.0</span></div></div>`:''}${externalStatusMarkup(o)}<div class="output-actions"><button class="btn" ${busy?'disabled':''} onclick="openOutputEdit('${key}')">Edit</button><button class="btn" ${busy?'disabled':''} onclick="openOutputRevision('${key}')">Request changes</button><button class="btn" ${busy?'disabled':''} onclick="openSubAssetComments(6,'${esc(o.commentsKey)}','${esc(o.label.replace(/'/g,"\\'"))}')">Collaborate</button><button class="btn" ${busy?'disabled':''} onclick="previewOutput('${key}')">Preview</button><button class="btn" ${busy?'disabled':''} onclick="openExternalApprovalRequest('output','${key}')">Send for agency approval</button><button class="btn primary" ${busy||o.approved?'disabled':''} onclick="acceptOutput('${key}')">${o.approved?'Accepted':'Accept output'}</button><button class="btn danger" ${busy?'disabled':''} onclick="excludeOutput('${key}')">${o.excluded?'Restore':'Exclude'}</button></div></div></div>`;}
function renderOutputs(){const values=Object.entries(state.outputs).filter(([,o])=>!o.excluded),approved=values.filter(([,o])=>o.approved);return `${stageHeader(6,'Adobe GenStudio channel outputs','Campaign Studio sends the accepted brief, audiences, approval record, production plan, selected assets, formats and mandatory requirements to Adobe GenStudio.')}<p class="answer-intro"><strong>Adobe GenStudio created the requested channel outputs.</strong> Each execution retains source lineage while adapting copy, layout, tracking and accessibility for its channel.</p><div class="callout info"><div><strong>Context sent to Adobe GenStudio</strong><br>Accepted brief · selected segments · Brief Approval record · production plan · selected DAM and GenStudio assets · mandatory language · tracking and accessibility requirements.</div></div><div class="artifact"><div class="artifact-head"><div class="artifact-title">${assetIconForStage(6)}Adobe GenStudio output package</div>${renderAssetHeaderRight(6,approved.length+' accepted')}</div><div class="artifact-body"><div class="output-list">${Object.entries(state.outputs).map(([k,o])=>renderOutputCard(k,o)).join('')}</div></div><div class="artifact-actions">${renderStandardAssetActions(6,'Accept '+approved.length+' accepted outputs',`acceptStageAsset(6,'Channel output package')`,`<button class="btn" onclick="toast('Accessibility, agency approval and tracking comparison opened')">Review technical details</button>`)}</div></div>`;}

function runOutputGenStudioRevision(key,request,reason){if(state.outputGeneratingKey)return;const o=state.outputs[key];state.outputGeneratingKey=key;renderAll();setTimeout(()=>{o.previousVersions.unshift({version:o.version,headline:o.headline,body:o.body,cta:o.cta,jobId:o.jobId,reason,externalApprovalStatus:o.externalApprovalStatus});o.version+=1;o.headline=request.headline||o.headline;o.body=request.body||o.body;o.cta=request.cta||o.cta;o.tracking=request.tracking||o.tracking;o.accessibility=request.accessibility||o.accessibility;o.jobId='GS-'+key.toUpperCase()+'-'+String(Date.now()).slice(-5);o.approved=false;resetExternalApproval(o);state.outputGeneratingKey=null;archiveDownstream(6,o.label+' regenerated in Adobe GenStudio');addActivity(`${o.label} v${o.version}.0 returned by Adobe GenStudio · external reapproval required`);renderAll();toast('Revised Adobe GenStudio output returned');},5000);}
function applySubAssetComments(){const key=state.commentAsset.key,meta=state.subAssetMeta[key]||{},chosen=(state.subAssetComments[key]||[]).filter(c=>c.selected&&!c.incorporated);if(!chosen.length){toast('Select at least one collaborator comment');return;}const assetIndex=state.assets.findIndex(a=>a.commentsKey===key);const outputEntry=Object.entries(state.outputs).find(([,o])=>o.commentsKey===key);chosen.forEach(c=>c.incorporated=true);if(assetIndex>=0){const a=state.assets[assetIndex];runAssetRegeneration(5,'Regenerating '+a.requirement+' in Adobe GenStudio from collaborator comments',()=>{a.version=(a.version||1)+1;a.generated=true;a.adapted=!!a.found;a.jobId='GS-ASSET-'+String(Date.now()).slice(-5);a.included=false;resetExternalApproval(a);archiveDownstream(5,a.requirement+' regenerated from collaborator comments');});return;}if(outputEntry){const [outputKey,o]=outputEntry;runOutputGenStudioRevision(outputKey,{headline:o.headline,body:o.body+' The selected collaborator guidance has been incorporated.',cta:o.cta},chosen.map(c=>c.text).join(' | '));return;}const i=meta.stage||state.commentAsset.stage||state.focusStage;runAssetRegeneration(i,'Regenerating '+(meta.title||'asset')+' from collaborator comments',()=>archiveDownstream(i,(meta.title||'Asset')+' regenerated from collaborator comments'));}

function renderLaunch(){const approved=Object.entries(state.outputs).filter(([,v])=>v.approved);const agencyRows=[...state.assets.filter(a=>a.included&&(a.generated||a.adapted)).map(a=>({name:a.requirement,status:a.externalApprovalStatus||'Not requested',version:a.version||1})),...approved.map(([,o])=>({name:o.label,status:o.externalApprovalStatus||'Not requested',version:o.version||1}))];const waiting=agencyRows.filter(r=>/Awaiting|Preparing|Reapproval/.test(r.status)).length;return `${stageHeader(7,'Launch handoff and mock publish','The Marketing Strategy & Campaign Brief Agent assembles the final campaign pack, including audience, asset, external-agency, tracking and destination readiness.')}<p class="answer-intro">The campaign is ready to hand off with <strong>${approved.length} accepted channel outputs</strong>, selected audience cohorts, registered governance records and asset-level agency-review history.</p><div class="artifact"><div class="artifact-head"><div class="artifact-title">${assetIconForStage(7)}Launch readiness and destination handoff</div>${renderAssetHeaderRight(7,state.published?'Published':waiting?'Conditions outstanding':'Ready for decision')}</div><div class="artifact-body"><div class="table"><div class="tr head"><div>Readiness item</div><div>Result</div><div>Evidence</div><div>Status</div></div><div class="tr"><div><strong>Audience lists</strong></div><div>${state.segments.filter(x=>x.selected).reduce((a,b)=>a+b.count,0).toLocaleString('en-GB')} CSIDs</div><div>Consent and eligibility rules</div><div class="row-status pass">Ready</div></div><div class="tr"><div><strong>Brief governance</strong></div><div>${state.acceptedAssets[3]?.id||'Approval record required'}</div><div>Workfront approval record</div><div class="row-status ${state.acceptedAssets[3]?'pass':'flag'}">${state.acceptedAssets[3]?'Ready':'Open'}</div></div><div class="tr"><div><strong>Final outputs</strong></div><div>${approved.length} accepted outputs</div><div>Adobe GenStudio records</div><div class="row-status pass">Ready</div></div><div class="tr"><div><strong>Tracking</strong></div><div>UTM, source and CSID exposure</div><div>Brief and production requirements</div><div class="row-status pass">Ready</div></div></div><div class="answer-section"><h3>External agency readiness</h3><div class="agency-readiness"><div class="agency-readiness-row head"><span>Asset</span><span>Version</span><span>Status</span></div>${agencyRows.map(r=>`<div class="agency-readiness-row"><span>${esc(r.name)}</span><span>v${r.version}.0</span><span class="${/^Approved/.test(r.status)?'agency-status-ok':/Awaiting|Preparing|Reapproval/.test(r.status)?'agency-status-wait':''}">${esc(r.status)}</span></div>`).join('')||`<div class="agency-readiness-row"><span>No external review requested</span><span>—</span><span>Not required</span></div>`}</div></div><div class="answer-section"><h3>Destination systems</h3>${approved.map(([key,v])=>`<div class="destination"><div><strong>${esc(v.label)}</strong><div class="field-hint">${key==='email'?'ESP journey and CRM activation':'LinkedIn Campaign Manager'}</div></div><span class="row-status pass">${state.published?'✓ Pushed':'Queued'}</span></div>`).join('')}<div class="destination"><div><strong>GA4 and campaign dashboard</strong><div class="field-hint">Tracking configuration and reporting handoff</div></div><span class="row-status pass">${state.published?'✓ Configured':'Queued'}</span></div></div>${state.published?`<div class="callout success">${ICON.check}<div><strong>Mock publish complete</strong><br>The final launch pack, agency approval history and audit trail are available for export.</div></div>`:`<div class="field"><label>Launch condition or note</label><textarea id="launchNote" placeholder="Optional condition for the launch record">${waiting?'Publish only after outstanding external agency reviews are resolved.':''}</textarea></div>`}</div><div class="artifact-actions">${state.published?`<button class="btn" onclick="exportState()">Export campaign state</button>`:`<button class="btn" onclick="openAssetEditModal(7)">Edit</button><button class="btn" onclick="regenerateStageFromChat(7)">Regenerate</button><button class="btn" ${selectedCommentsForStage(7)?'':'disabled'} onclick="applyStageComments(7)">Generate with collaborator comments (${selectedCommentsForStage(7)})</button><button class="btn" onclick="holdLaunch()">Hold launch</button><button class="btn primary" onclick="publishCampaign(${waiting?'true':'false'})">${waiting?'Approve with agency conditions':'Confirm publish'}</button>`}${renderInlineOperation(7)}</div></div>`;}
// Add the specialist agent to the existing Teams participant configuration.
const coordinator=TEAMS_PARTICIPANTS.find(p=>p.initials==='AI');if(coordinator){coordinator.role='AI Orchestration Agent';coordinator.defaultStatus='Following the discussion';}
if(!TEAMS_PARTICIPANTS.some(p=>p.initials==='CA'))TEAMS_PARTICIPANTS.push({id:'creation-agent',initials:'CA',name:'Marketing Strategy & Campaign Brief Agent',role:'AI Campaign Specialist',type:'agent',presence:'available',defaultStatus:'Waiting to be invited'});
Object.assign(teamsState,{creationAgentAdded:false,contextShared:false,coordinatorOpportunityReady:false,creationAgentIntroReady:false,provenanceReady:false,systemEvents:[]});
teamsState.thinkingStatuses=['Reviewing context shared by Campaign Coordinator…','Searching relevant Teams conversations…','Reviewing Outlook emails…','Reading SharePoint documents…','Preparing the initial iPortal campaign brief…'];

function renderTeamsPost(m){if(m.systemEvent)return `<div class="teams-system-event ${m.context?'context-share':''}"><span class="teams-system-event-icon">${m.context?'↗':'＋'}</span><span>${esc(m.text)}</span><time>${esc(m.time)}</time></div>`;const profile=teamsParticipant(m.initials);if(m.agentRecommendation){return `<article class="teams-post agent-post teams-agent-recommendation-post"><div class="teams-post-top"><div class="teams-avatar agent">${esc(profile.initials)}</div><div class="teams-author"><strong>${esc(profile.name)}</strong><span>${esc(profile.role)} · ${esc(m.time)}</span></div></div><div class="teams-agent-listening">Campaign opportunity assessed</div>${renderTeamsRecommendation()}</article>`;}return `<article class="teams-post ${profile.type==='agent'?'agent-message':''} ${m.humanConfirmation?'teams-human-confirmation':''}"><div class="teams-post-top"><div class="teams-avatar ${profile.type==='agent'?'agent':''}">${esc(profile.initials)}</div><div class="teams-author"><strong>${esc(profile.name)}</strong>${profile.type==='agent'?'<span class="agent-badge">AI Agent</span>':''}<span>${esc(profile.role)} · ${esc(m.time)}</span></div></div><p>${esc(m.text)}</p><div class="teams-post-actions"><button class="teams-mini-action teams-reaction ${teamsState.reactionPulse===m.id?'teams-reaction-pop':''}" onclick="reactTeams('${m.id}')">👍 <span>${m.reactions||0}</span></button><button class="teams-mini-action" onclick="toggleTeamReply('${m.id}')">Reply</button><button class="teams-mini-action">•••</button></div>${m.replies&&m.replies.length||teamsState.typing&&teamsState.typing.kind==='reply'&&teamsState.typing.parentId===m.id?`<div class="teams-thread">${(m.replies||[]).map(r=>{const rp=teamsParticipant(r.initials);return `<div class="teams-reply"><div class="teams-avatar ${rp.type==='agent'?'agent':''}">${esc(rp.initials)}</div><div class="teams-reply-body"><strong>${esc(rp.name)}</strong>${esc(r.text)}<span>${esc(r.time)}</span></div></div>`;}).join('')}${teamsReplyTyping(m.id)}</div>`:''}${teamsState.replyOpen===m.id?`<div class="teams-inline-reply"><input id="teamReply-${m.id}" placeholder="Reply in this thread…"><button onclick="postTeamReply('${m.id}')">Reply</button></div>`:''}</article>`;}
function teamsParticipantActivity(){if(teamsState.typing){const p=teamsParticipant(teamsState.typing.initials);return {initials:p.initials,status:teamsState.typing.kind==='reply'?'Replying in thread…':'Typing…'};}if(teamsState.generating)return {initials:'CA',status:teamsState.thinkingStatuses[teamsState.thinkingStep]};if(teamsState.summaryReady)return {initials:'CA',status:'Brief prepared'};if(teamsState.agentRecommendationReady&&!teamsState.authorised)return {initials:'CA',status:'Waiting for confirmation'};if(teamsState.activeParticipant)return {initials:teamsState.activeParticipant,status:teamsState.activeParticipantStatus||'Contributing…'};return null;}
function renderTeamsPeople(){const panel=document.getElementById('teamsPeople');if(!panel)return;const active=teamsParticipantActivity();panel.classList.toggle('open',!!teamsState.peopleOpen);panel.innerHTML=`<div class="teams-people-head"><div><h3>People in this discussion</h3><div class="teams-people-count">${TEAMS_PARTICIPANTS.length} participants</div></div><button class="teams-people-close" onclick="toggleTeamsPeople(false)">×</button></div>${TEAMS_PARTICIPANTS.map(p=>{const isActive=active&&active.initials===p.initials;let status=isActive?active.status:p.defaultStatus;if(p.initials==='AI')status=isActive?active.status:(teamsState.contextShared?'Retaining campaign provenance':teamsState.coordinatorOpportunityReady?'Specialist invited':'Following the discussion');if(p.initials==='CA')status=isActive?active.status:(teamsState.summaryReady?'Brief prepared':teamsState.generating?teamsState.thinkingStatuses[teamsState.thinkingStep]:teamsState.agentRecommendationReady&&!teamsState.authorised?'Waiting for confirmation':teamsState.creationAgentIntroReady?'Listening to the team':teamsState.creationAgentAdded?'Context received':'Waiting to be invited');return `<div class="teams-person ${isActive?'active':''} ${p.type==='agent'?'agent-row':''}"><div class="teams-person-avatar-wrap"><div class="teams-avatar ${p.type==='agent'?'agent':''}">${esc(p.initials)}</div><span class="teams-person-presence-dot ${p.presence==='away'?'away':''}"></span></div><div class="teams-person-copy"><strong>${esc(p.name)}</strong><span class="teams-person-role">${esc(p.role)}</span><span class="teams-person-status">${esc(status)}</span></div></div>`;}).join('')}`;const backdrop=document.getElementById('teamsPeopleBackdrop');if(backdrop)backdrop.classList.toggle('open',!!teamsState.peopleOpen);}
function renderTeams(){const feed=document.getElementById('teamsFeedInner');if(!feed)return;const events=(teamsState.systemEvents||[]).map(e=>`<div class="teams-system-event ${e.context?'context-share':''}"><span class="teams-system-event-icon">${e.context?'↗':'＋'}</span><span>${esc(e.text)}</span><time>${esc(e.time)}</time></div>`).join('');const posts=teamsState.messages.map(renderTeamsPost).join('');let dynamic='';if(teamsState.generating){dynamic=`<div class="teams-post agent-post agent-message"><div class="teams-post-top"><div class="teams-avatar agent">CA</div><div class="teams-author"><strong>Marketing Strategy & Campaign Brief Agent</strong><span>AI Campaign Specialist · creating campaign</span></div></div><div class="teams-thinking" style="margin:12px 0 0 41px"><div class="teams-thinking-copy">${esc(teamsState.thinkingStatuses[teamsState.thinkingStep])} <span class="thinking-dots"><span></span><span></span><span></span></span></div></div></div>`;}else if(teamsState.summaryReady){dynamic=`<div class="teams-post agent-post agent-message"><div class="teams-post-top"><div class="teams-avatar agent">CA</div><div class="teams-author"><strong>Marketing Strategy & Campaign Brief Agent</strong><span>AI Campaign Specialist · campaign prepared</span></div></div>${renderTeamsSummary()}</div>`;}feed.innerHTML=events+posts+teamsTypingCard()+dynamic;const chip=document.getElementById('teamsAgentChip');if(chip)chip.textContent=teamsState.generating?'Marketing Strategy & Campaign Brief Agent preparing brief':teamsState.summaryReady?'Campaign brief prepared':teamsState.agentRecommendationReady&&!teamsState.authorised?'Marketing Strategy & Campaign Brief Agent awaiting approval':'Campaign support active';renderTeamsPeople();requestAnimationFrame(()=>{const c=document.getElementById('teamsFeed');if(c)c.scrollTo({top:c.scrollHeight,behavior:'smooth'});});}
function renderTeamsRecommendation(){return `<p class="teams-opportunity-intro">Based on the completed discussion, this looks like a strong candidate for a targeted iPortal adoption campaign.</p><div class="teams-opportunity-compact"><div class="teams-opportunity-row"><strong>Challenge</strong><span>Clients are underusing available iPortal self-service capabilities.</span></div><div class="teams-opportunity-row"><strong>Audience</strong><span>Servicing-heavy, digitally dormant and advanced digital-user cohorts.</span></div><div class="teams-opportunity-row"><strong>Opportunity</strong><span>Improve awareness, first meaningful use and deeper feature adoption.</span></div><div class="teams-opportunity-row"><strong>Open questions</strong><span>Adoption baseline, eligible population, consent and claims evidence.</span></div></div><div class="teams-agent-question compact"><strong>Would you like me to go ahead?</strong>I can use this conversation and the connected collaboration sources to create a Campaign Studio workspace and prepare the initial brief.</div><div class="teams-agent-actions"><button class="teams-agent-primary" onclick="approveCampaignCreation()">Yes, create the campaign brief</button><button class="teams-agent-secondary" onclick="useTeamsPrompt()">Draft a response</button></div><div class="teams-reading-note">Waiting for the team’s confirmation</div>`;}
function renderTeamsSummary(){return `<p>Thanks, Sarah. I received the full discussion context from the Campaign Coordinator, reviewed the connected sources and created the initial Campaign Studio workspace.</p><div class="teams-summary-card"><div class="teams-summary-head"><strong>iPortal campaign workspace</strong><span>Initial campaign brief prepared</span></div><div class="teams-summary-body"><div class="teams-summary-grid"><div class="teams-summary-item"><label>Proposed campaign</label><div>iPortal Digital Engagement Campaign</div></div><div class="teams-summary-item"><label>Problem statement</label><div>Clients are not consistently discovering or using available self-service capabilities.</div></div><div class="teams-summary-item"><label>Audience considerations</label><div>Servicing-heavy users, digitally dormant clients and advanced digital users.</div></div><div class="teams-summary-item"><label>Sources reviewed</label><div>Teams conversation, Outlook emails and SharePoint campaign documents.</div></div></div><button class="teams-open-brief" onclick="openCampaignStudioFromTeams()"><span>Open the generated iPortal campaign brief</span><span>→</span></button></div></div>`;}
async function runTeamsConversationSequence(){if(teamsState.sequenceRunning||teamsState.summaryReady)return;const runId=++teamsState.runId;teamsState.sequenceRunning=true;teamsState.systemEvents=[{text:'Campaign Coordinator was added to the iPortal Adoption channel.',time:'08:58'}];teamsState.activeParticipant='AI';teamsState.activeParticipantStatus='Added to channel';renderTeams();await teamsWait(1300);if(!teamsRunCurrent(runId))return;teamsState.typing={kind:'message',initials:'AI',name:'Campaign Coordinator',role:'AI Orchestration Agent'};renderTeams();await teamsWait(1900);if(!teamsRunCurrent(runId))return;teamsState.typing=null;teamsState.messages.push({id:'agent-intro',initials:'AI',name:'Campaign Coordinator',role:'AI Orchestration Agent',time:'08:59',text:'Hi everyone. I’ll follow the discussion, retain the key context and identify where specialist campaign support may be useful. I will bring in the appropriate agent if the conversation points to a campaign opportunity.',reactions:0,replies:[]});teamsState.activeParticipant='AI';teamsState.activeParticipantStatus='Following the discussion';renderTeams();await teamsWait(1700);for(let i=0;i<=5;i++){if(!await showTeamsScriptItem(TEAMS_DISCUSSION[i],runId,i===0))return;}await teamsWait(1800);if(!teamsRunCurrent(runId))return;teamsState.typing={kind:'message',initials:'AI',name:'Campaign Coordinator',role:'AI Orchestration Agent'};teamsState.activeParticipant='AI';teamsState.activeParticipantStatus='Identifying specialist support…';renderTeams();await teamsWait(2200);if(!teamsRunCurrent(runId))return;teamsState.typing=null;teamsState.messages.push({id:'coordinator-opportunity',initials:'AI',name:'Campaign Coordinator',role:'AI Orchestration Agent',time:'09:18',text:'I’m seeing a potential campaign opportunity. The team has identified a clear adoption problem, distinct behavioural cohorts and a need for coordinated activation. I’m bringing the Marketing Strategy & Campaign Brief Agent into the conversation to assess whether a structured campaign brief is the right next step.',reactions:1,replies:[]});teamsState.coordinatorOpportunityReady=true;renderTeams();await teamsWait(1300);teamsState.messages.push({systemEvent:true,text:'Marketing Strategy & Campaign Brief Agent was added to the iPortal Adoption channel by Campaign Coordinator.',time:'09:19'});teamsState.creationAgentAdded=true;teamsState.activeParticipant='CA';teamsState.activeParticipantStatus='Invited to channel';renderTeams();await teamsWait(1100);teamsState.messages.push({systemEvent:true,text:'Campaign Coordinator shared the business problem, participant comments, audience hypotheses, channel considerations, evidence gaps and source references with Marketing Strategy & Campaign Brief Agent.',time:'09:20',context:true});teamsState.contextShared=true;renderTeams();await teamsWait(1300);teamsState.typing={kind:'message',initials:'CA',name:'Marketing Strategy & Campaign Brief Agent',role:'AI Campaign Specialist'};teamsState.activeParticipant='CA';teamsState.activeParticipantStatus='Context received';renderTeams();await teamsWait(2000);if(!teamsRunCurrent(runId))return;teamsState.typing=null;teamsState.creationAgentIntroReady=false;teamsState.creationAgentIntroReady=true;teamsState.activeParticipant='CA';teamsState.activeParticipantStatus='Listening to the team';renderTeams();await teamsWait(1600);for(let i=6;i<TEAMS_DISCUSSION.length;i++){if(!await showTeamsScriptItem(TEAMS_DISCUSSION[i],runId))return;}await teamsWait(2000);if(!teamsRunCurrent(runId))return;teamsState.typing={kind:'message',initials:'CA',name:'Marketing Strategy & Campaign Brief Agent',role:'AI Campaign Specialist'};teamsState.activeParticipant='CA';teamsState.activeParticipantStatus='Assessing campaign opportunity…';renderTeams();await teamsWait(2500);if(!teamsRunCurrent(runId))return;teamsState.typing=null;teamsState.messages.push({id:'agent-recommendation',initials:'CA',name:'Marketing Strategy & Campaign Brief Agent',role:'AI Campaign Specialist',time:'09:36',agentRecommendation:true,reactions:0,replies:[]});teamsState.agentRecommendationReady=true;teamsState.activeParticipant='CA';teamsState.activeParticipantStatus='Waiting for confirmation';renderTeams();await teamsWait(5000);if(!teamsRunCurrent(runId)||teamsState.authorised)return;await queueSarahApproval(false,runId);}
async function queueSarahApproval(fromUser=false,runId=teamsState.runId){if(teamsState.authorised||teamsState.approvalInProgress||teamsState.generating||teamsState.summaryReady||!teamsState.agentRecommendationReady)return;teamsState.approvalInProgress=true;if(!fromUser){teamsState.typing={kind:'message',initials:'SC',name:'Sarah Chen',role:'Campaign Manager'};teamsState.activeParticipant='SC';teamsState.activeParticipantStatus='Typing…';renderTeams();await teamsWait(2200);if(!teamsRunCurrent(runId)||teamsState.authorised)return;teamsState.typing=null;teamsState.messages.push({id:'approval-'+Date.now(),initials:'SC',name:'Sarah Chen',role:'Campaign Manager',time:'09:38',text:'Yes, please go ahead. Use this discussion as the starting context and review the relevant Teams conversations, Outlook emails and SharePoint documents before creating the initial iPortal campaign brief.',reactions:1,replies:[],humanConfirmation:true});}teamsState.authorised=true;teamsState.approvalInProgress=false;teamsState.activeParticipant='SC';teamsState.activeParticipantStatus='Authorising campaign creation…';renderTeams();await teamsWait(900);teamsState.typing={kind:'message',initials:'CA',name:'Marketing Strategy & Campaign Brief Agent',role:'AI Campaign Specialist'};teamsState.activeParticipant='CA';teamsState.activeParticipantStatus='Acknowledging request…';renderTeams();await teamsWait(1500);teamsState.typing=null;teamsState.messages.push({id:'creation-ack',initials:'CA',name:'Marketing Strategy & Campaign Brief Agent',role:'AI Campaign Specialist',time:'09:39',text:'Understood. I’ll use the shared discussion context and review the connected sources before preparing the brief.',reactions:0,replies:[]});renderTeams();await teamsWait(800);teamsState.typing={kind:'message',initials:'AI',name:'Campaign Coordinator',role:'AI Orchestration Agent'};teamsState.activeParticipant='AI';teamsState.activeParticipantStatus='Retaining campaign provenance…';renderTeams();await teamsWait(1300);teamsState.typing=null;teamsState.provenanceReady=false;teamsState.provenanceReady=true;renderTeams();await teamsWait(650);if(teamsRunCurrent(runId))startTeamsCreation();}
async function startTeamsCreation(){if(teamsState.generating||teamsState.summaryReady||!teamsState.authorised)return;const runId=teamsState.runId;teamsState.generating=true;teamsState.thinkingStep=0;teamsState.activeParticipant='CA';teamsState.activeParticipantStatus=teamsState.thinkingStatuses[0];renderTeams();for(let i=1;i<teamsState.thinkingStatuses.length;i++){await teamsWait(1000);if(!teamsRunCurrent(runId)||!teamsState.generating)return;teamsState.thinkingStep=i;renderTeams();}await teamsWait(1000);if(!teamsRunCurrent(runId)||!teamsState.generating)return;teamsState.generating=false;teamsState.summaryReady=true;teamsState.sequenceRunning=false;renderTeams();}
function replayTeamsDiscussion(){teamsState.runId+=1;Object.assign(teamsState,{generating:false,summaryReady:false,authorised:false,replyOpen:null,thinkingStep:0,messages:[],typing:null,systemEventShown:false,agentIntroReady:false,acknowledgementReady:false,agentRecommendationReady:false,sequenceRunning:false,approvalInProgress:false,reactionPulse:null,peopleOpen:false,activeParticipant:null,activeParticipantStatus:'',creationAgentAdded:false,contextShared:false,coordinatorOpportunityReady:false,creationAgentIntroReady:false,provenanceReady:false,systemEvents:[]});renderTeams();setTimeout(runTeamsConversationSequence,500);}
function openCampaignStudioFromTeams(){if(!teamsState.summaryReady){toast('Wait for the Marketing Strategy & Campaign Brief Agent to finish preparing the brief');return;}const teams=document.getElementById('teamsExperience'),app=document.getElementById('appRoot');teams.style.display='none';app.classList.remove('studio-hidden');app.classList.remove('not-started');state.started=true;state.initialPrompt='Create the iPortal Digital Engagement Campaign brief from the multi-agent working-group discussion, relevant Teams conversations, Outlook emails and SharePoint documents.';state.sourceSearchComplete=true;state.completed.add(0);state.stage=1;state.focusStage=1;state.generatedAssets[1]=true;state.stagePrompts[1]=state.initialPrompt;state.activities.unshift('Marketing Strategy & Campaign Brief Agent created the workspace from the team discussion; Campaign Coordinator retained provenance and source lineage');const name=document.querySelector('.agent-name');if(name)name.textContent='Marketing Strategy & Campaign Brief Agent';const sub=document.querySelector('.agent-sub');if(sub)sub.textContent='Specialist campaign agent · context orchestrated by Campaign Coordinator';renderAll({scrollToStage:1});}
function assistantMessage(content){return `<div class="message assistant"><div class="avatar">${ICON.bot}</div><div class="bubble"><div class="assistant-label">Marketing Strategy & Campaign Brief Agent</div>${content}</div></div>`;}
function useTeamsPrompt(){const input=document.getElementById('teamsComposer');input.value='Yes, please go ahead. Use this discussion as the starting context and review the relevant Teams conversations, Outlook emails and SharePoint documents before creating the initial iPortal campaign brief.';input.focus();}

function renderGeneratingState(i,label){const def=assetDef(i),copy=label||state.generationLabel||def.generate;const stageStatuses=i===5?['Reading the accepted campaign brief…','Reviewing selected audience and approval requirements…','Checking production specifications…','Searching Adobe DAM…','Comparing approved assets with channel requirements…']:i===6?['Packaging the accepted campaign context…','Sending selected assets and requirements to Adobe GenStudio…','Generating the Email output…','Generating the LinkedIn output…','Applying format, accessibility and mandatory-content requirements…']:null;const status=stageStatuses?stageStatuses[Math.min(state.stageThinkingStep,stageStatuses.length-1)]:'Reviewing accepted decisions, source grounding, collaborator input and workflow requirements.';return `${stageHeader(i,copy,`The Marketing Strategy & Campaign Brief Agent is synthesising campaign context and creating the ${def.name.toLowerCase()}.`)}<div class="generation-card"><div class="generation-visual"><div class="generation-doc">${ICON.bot}</div></div><div class="generation-copy"><h3>${esc(copy)} <span class="thinking-dots"><span></span><span></span><span></span></span></h3><p>${esc(status)}</p><div class="generation-time">Marketing Strategy & Campaign Brief Agent is thinking · approximately 5 seconds</div></div></div>`;}
function renderInlineOperation(i){if(state.generatingStage!==i||state.inlineOperationStage!==i)return '';const label=state.inlineOperationLabel||state.generationLabel||('Updating '+assetDef(i).name);return `<div class="inline-operation-state" id="inline-operation-${i}"><div class="inline-operation-avatar">${ICON.bot}</div><div class="inline-operation-copy"><strong>${esc(label)} <span class="inline-operation-dots"><i></i><i></i><i></i></span></strong><span>The Marketing Strategy & Campaign Brief Agent is applying the requested change in place. The current asset remains visible while the new draft is prepared.</span></div></div>`;}

